// Package git wraps the git binary with the operations the deployment
// commands need. It is deliberately narrow: only what is used, and nothing
// that would tempt a caller into arbitrary git.
package git

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/command"
)

// Client is a typed wrapper over the git binary rooted at a working directory.
type Client struct {
	Runner command.Runner
	Dir    string
}

func (g Client) run(ctx context.Context, args ...string) (string, error) {
	stdout, _, err := g.Runner.Run(ctx, g.Dir, "git", args...)
	return strings.TrimSpace(string(stdout)), err
}

// HEAD returns the full commit sha of HEAD. Full, not abbreviated: an
// abbreviated sha is ambiguous as a registry tag and as an ancestry argument.
func (g Client) HEAD(ctx context.Context) (string, error) {
	sha, err := g.run(ctx, "rev-parse", "HEAD")
	if err != nil {
		return "", fmt.Errorf("resolve HEAD: %w", err)
	}
	return sha, nil
}

// Status returns porcelain status lines limited to paths, or to the whole tree
// when no paths are given.
//
// Untracked files are listed individually rather than collapsed to their
// directory: these lines are shown to the user when a deploy is refused, and
// "component/" is a much less useful answer than the files that are actually
// uncommitted.
func (g Client) Status(ctx context.Context, paths ...string) ([]string, error) {
	args := []string{"status", "--porcelain", "--untracked-files=all"}
	if len(paths) > 0 {
		args = append(args, "--")
		args = append(args, paths...)
	}
	out, err := g.run(ctx, args...)
	if err != nil {
		return nil, fmt.Errorf("read working tree status: %w", err)
	}
	if out == "" {
		return nil, nil
	}
	return strings.Split(out, "\n"), nil
}

// Fetch updates remote-tracking refs. Callers that are about to reason about
// ancestry must fetch first: a stale origin/<branch> makes a pushed commit look
// unpushed.
func (g Client) Fetch(ctx context.Context, remote string, refspecs ...string) error {
	args := append([]string{"fetch", "--quiet", remote}, refspecs...)
	if _, err := g.run(ctx, args...); err != nil {
		return fmt.Errorf("fetch %s: %w", remote, err)
	}
	return nil
}

// DefaultBranch returns the remote's default branch name, preferring the
// symbolic ref that git records at clone time and falling back to querying the
// remote. Hardcoding "main" would be wrong for any repository that never
// renamed from master.
func (g Client) DefaultBranch(ctx context.Context, remote string) (string, error) {
	if out, err := g.run(ctx, "symbolic-ref", "--short", "refs/remotes/"+remote+"/HEAD"); err == nil {
		// refs/remotes/origin/HEAD reads back as "origin/main".
		if _, branch, ok := strings.Cut(out, "/"); ok && branch != "" {
			return branch, nil
		}
	}

	// Freshly cloned mirrors and worktrees created with --single-branch may
	// have no origin/HEAD; ask the remote directly.
	out, err := g.run(ctx, "ls-remote", "--symref", remote, "HEAD")
	if err != nil {
		return "", fmt.Errorf("determine default branch of %s: %w", remote, err)
	}
	for line := range strings.SplitSeq(out, "\n") {
		// "ref: refs/heads/main\tHEAD"
		rest, ok := strings.CutPrefix(strings.TrimSpace(line), "ref: refs/heads/")
		if !ok {
			continue
		}
		if branch, _, _ := strings.Cut(rest, "\t"); branch != "" {
			return branch, nil
		}
	}
	return "", fmt.Errorf("determine default branch of %s: no symref in ls-remote output", remote)
}

// IsAncestor reports whether ancestor is an ancestor of descendant. Equal
// commits count as ancestors, matching git's own semantics.
func (g Client) IsAncestor(ctx context.Context, ancestor, descendant string) (bool, error) {
	_, err := g.run(ctx, "merge-base", "--is-ancestor", ancestor, descendant)
	if err == nil {
		return true, nil
	}
	// git exits 1 for "not an ancestor" and 128 for a bad revision, so only
	// exit 1 may be read as a clean negative answer.
	if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
		return false, nil
	}
	return false, fmt.Errorf("check whether %s is an ancestor of %s: %w", ShortSHA(ancestor), ShortSHA(descendant), err)
}

// Add stages paths.
func (g Client) Add(ctx context.Context, paths ...string) error {
	args := append([]string{"add", "--"}, paths...)
	if _, err := g.run(ctx, args...); err != nil {
		return fmt.Errorf("stage changes: %w", err)
	}
	return nil
}

// CheckoutPaths discards working-tree changes under paths. Always pass an
// explicit path: an unscoped revert would throw away anything else in the
// worktree, including a concurrent run's staged work.
func (g Client) CheckoutPaths(ctx context.Context, paths ...string) error {
	if len(paths) == 0 {
		return errors.New("CheckoutPaths requires at least one path")
	}
	args := append([]string{"checkout", "--"}, paths...)
	if _, err := g.run(ctx, args...); err != nil {
		return fmt.Errorf("discard changes: %w", err)
	}
	return nil
}

// CreateBranch creates name at startPoint and checks it out, resetting it if it
// already exists locally.
//
// The reset is deliberate: the only local branches in a cached checkout are ones
// a previous run of this CLI left behind, and reusing a stale one would build a
// commit on top of whatever that run happened to do.
func (g Client) CreateBranch(ctx context.Context, name, startPoint string) error {
	if _, err := g.run(ctx, "checkout", "-B", name, startPoint); err != nil {
		return fmt.Errorf("create branch %s at %s: %w", name, startPoint, err)
	}
	return nil
}

// Switch checks out an existing ref.
//
// Callers holding a shared cached checkout must switch back to the default
// branch when they are done: the refresh on the next Open resets whatever branch
// is current to the default branch's remote head, which would silently discard a
// feature branch's commits.
func (g Client) Switch(ctx context.Context, ref string) error {
	if _, err := g.run(ctx, "checkout", ref); err != nil {
		return fmt.Errorf("switch to %s: %w", ref, err)
	}
	return nil
}

// ResetHard moves the branch and working tree to ref.
func (g Client) ResetHard(ctx context.Context, ref string) error {
	if _, err := g.run(ctx, "reset", "--hard", ref); err != nil {
		return fmt.Errorf("reset to %s: %w", ref, err)
	}
	return nil
}

// Clean removes untracked files and directories.
func (g Client) Clean(ctx context.Context) error {
	if _, err := g.run(ctx, "clean", "-fdq"); err != nil {
		return fmt.Errorf("clean working tree: %w", err)
	}
	return nil
}

// RevParse resolves any revision expression to a full sha.
func (g Client) RevParse(ctx context.Context, rev string) (string, error) {
	sha, err := g.run(ctx, "rev-parse", rev)
	if err != nil {
		return "", fmt.Errorf("resolve %s: %w", rev, err)
	}
	return sha, nil
}

// Clone clones url into dir. dir must not already exist.
func Clone(ctx context.Context, r command.Runner, url, dir string) error {
	if _, _, err := r.Run(ctx, "", "git", "clone", "--quiet", url, dir); err != nil {
		return fmt.Errorf("clone %s: %w", url, err)
	}
	return nil
}

// ShortSHA abbreviates a sha for messages, leaving non-sha revisions alone.
func ShortSHA(rev string) string {
	if len(rev) >= 40 {
		return rev[:7]
	}
	return rev
}

// Commit records the staged changes. Each message becomes a paragraph, which is
// how a subject line and a trailer block are produced without a temporary file:
// git separates -m arguments with a blank line, and trailers only need to be
// the final paragraph to be parseable by `git log --format=%(trailers)`.
//
// Nothing is staged implicitly — there is no -a — so the caller decides exactly
// what the commit contains.
func (g Client) Commit(ctx context.Context, messages ...string) error {
	if len(messages) == 0 {
		return errors.New("Commit requires at least a subject")
	}
	args := []string{"commit", "--quiet"}
	for _, m := range messages {
		args = append(args, "-m", m)
	}
	if _, err := g.run(ctx, args...); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

// Tag creates an annotated tag at commit. Annotated rather than lightweight:
// it carries the author, date and message that make the tag worth reading in
// `git log`, which is the only reason the tag exists.
//
// Creating a tag that already exists is an error rather than a silent move —
// a release tag that quietly relocates would misrepresent history.
func (g Client) Tag(ctx context.Context, name, message, commit string) error {
	if _, err := g.run(ctx, "tag", "--annotate", "--message", message, name, commit); err != nil {
		return fmt.Errorf("tag %s: %w", name, err)
	}
	return nil
}

// TagCommit resolves an annotated or lightweight tag to the commit it points
// at. The bool reports whether the tag exists locally at all, so a caller can
// tell "no such tag" from a genuine failure to read it.
func (g Client) TagCommit(ctx context.Context, name string) (string, bool, error) {
	// ^{commit} dereferences an annotated tag to its commit; without it the
	// answer would be the tag object's own sha, which never matches a commit.
	sha, err := g.run(ctx, "rev-parse", "--verify", "--quiet", "refs/tags/"+name+"^{commit}")
	if err == nil {
		return sha, sha != "", nil
	}
	// --quiet makes an unknown ref exit 1 with no output, which is the answer
	// rather than a failure.
	if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
		return "", false, nil
	}
	return "", false, fmt.Errorf("resolve tag %s: %w", name, err)
}

// LogCommit is one commit in a range, reduced to what release notes need.
type LogCommit struct {
	SHA     string
	Subject string
}

// LastCommit returns the sha of the most recent commit on rev that changed path,
// and whether there was one.
//
// Merges are not excluded here, unlike Log: this answers "which commit put the
// file in its current state", and a merge that resolved the file really is that
// commit.
func (g Client) LastCommit(ctx context.Context, rev, path string) (string, bool, error) {
	sha, _, found, err := g.LastCommitAt(ctx, rev, path)
	return sha, found, err
}

// LastCommitAt is LastCommit with the commit's timestamp, which is what dates a
// deployment: an overlay changed when the commit that changed it landed.
//
// The committer date rather than the author date. Publish rebases and retries
// when the push races another deployment, which rewrites the committer date and
// leaves the author date at the first attempt; the later of the two is when the
// change actually reached the branch.
func (g Client) LastCommitAt(ctx context.Context, rev, path string) (string, time.Time, bool, error) {
	// NUL-separated for the same reason Log is: the fields are fixed-width here,
	// but one delimiter convention in this file is one fewer thing to get wrong.
	out, err := g.run(ctx, "log", "-1", "--format=%H%x00%cI", rev, "--", path)
	if err != nil {
		return "", time.Time{}, false, fmt.Errorf("read last commit for %s: %w", path, err)
	}
	if out == "" {
		return "", time.Time{}, false, nil
	}

	sha, date, ok := strings.Cut(out, "\x00")
	if !ok {
		return "", time.Time{}, false, fmt.Errorf("read last commit for %s: unexpected git log output %q", path, out)
	}
	at, err := time.Parse(time.RFC3339, date)
	if err != nil {
		return "", time.Time{}, false, fmt.Errorf("read last commit for %s: parse commit date %q: %w", path, date, err)
	}
	return sha, at, true, nil
}

// Log lists the commits in revRange, most recent first, limited to paths when
// any are given.
//
// The two fields are separated by a NUL and the records by a newline: a commit
// subject may contain anything except a newline, so a printable delimiter
// could appear inside one and split a record in the wrong place.
func (g Client) Log(ctx context.Context, revRange string, paths ...string) ([]LogCommit, error) {
	args := []string{"log", "--format=%H%x00%s", "--no-merges", revRange}
	if len(paths) > 0 {
		args = append(args, "--")
		args = append(args, paths...)
	}
	out, err := g.run(ctx, args...)
	if err != nil {
		return nil, fmt.Errorf("read log for %s: %w", revRange, err)
	}
	if out == "" {
		return nil, nil
	}

	var commits []LogCommit
	for line := range strings.SplitSeq(out, "\n") {
		sha, subject, ok := strings.Cut(line, "\x00")
		if !ok {
			continue
		}
		commits = append(commits, LogCommit{SHA: sha, Subject: subject})
	}
	return commits, nil
}

// Push pushes refspec to remote.
//
// A rejection is reported as *PushRejectedError so callers can rebase and retry,
// distinguished from an authentication or network failure where retrying is
// pointless.
func (g Client) Push(ctx context.Context, remote, refspec string) error {
	_, err := g.run(ctx, "push", "--quiet", remote, refspec)
	if err == nil {
		return nil
	}
	if ee, ok := errors.AsType[*command.ExitError](err); ok && isRejection(ee.Stderr) {
		return &PushRejectedError{Remote: remote, Refspec: refspec, Stderr: ee.Stderr}
	}
	return fmt.Errorf("push %s %s: %w", remote, refspec, err)
}

// PushRejectedError reports that the remote refused the push because it has
// commits we do not have.
type PushRejectedError struct {
	Remote  string
	Refspec string
	Stderr  string
}

func (e *PushRejectedError) Error() string {
	return fmt.Sprintf("push to %s was rejected: %s", e.Remote, strings.TrimSpace(e.Stderr))
}

// isRejection recognises a non-fast-forward refusal. git has no distinct exit
// code for it, so the message is the only signal available; the phrases below
// are the ones git itself emits.
func isRejection(stderr string) bool {
	for _, marker := range []string{"[rejected]", "non-fast-forward", "fetch first", "Updates were rejected"} {
		if strings.Contains(stderr, marker) {
			return true
		}
	}
	return false
}

// Rebase replays the current branch onto upstream.
//
// A conflict is reported as *RebaseConflictError with the rebase left in
// progress, so the caller can decide — this package must not abort on the
// caller's behalf, because whether a conflict is recoverable is policy.
func (g Client) Rebase(ctx context.Context, upstream string) error {
	_, err := g.run(ctx, "rebase", upstream)
	if err == nil {
		return nil
	}
	if ee, ok := errors.AsType[*command.ExitError](err); ok {
		return &RebaseConflictError{Upstream: upstream, Stderr: ee.Stderr}
	}
	return fmt.Errorf("rebase onto %s: %w", upstream, err)
}

// RebaseConflictError reports a rebase that stopped, leaving the repository
// mid-rebase.
type RebaseConflictError struct {
	Upstream string
	Stderr   string
}

func (e *RebaseConflictError) Error() string {
	return fmt.Sprintf("rebase onto %s stopped: %s", e.Upstream, strings.TrimSpace(e.Stderr))
}

// RebaseAbort restores the state from before a rebase.
func (g Client) RebaseAbort(ctx context.Context) error {
	if _, err := g.run(ctx, "rebase", "--abort"); err != nil {
		return fmt.Errorf("abort rebase: %w", err)
	}
	return nil
}

// Trailers returns the trailer block of a commit message as ordered pairs.
// Duplicate keys are preserved, since a commit may legitimately repeat one.
func (g Client) Trailers(ctx context.Context, rev string) ([]Trailer, error) {
	out, err := g.run(ctx, "log", "-1", "--format=%(trailers:only=true)", rev)
	if err != nil {
		return nil, fmt.Errorf("read trailers of %s: %w", ShortSHA(rev), err)
	}
	var trailers []Trailer
	for line := range strings.SplitSeq(out, "\n") {
		key, value, ok := strings.Cut(strings.TrimSpace(line), ":")
		if !ok || key == "" {
			continue
		}
		trailers = append(trailers, Trailer{Key: key, Value: strings.TrimSpace(value)})
	}
	return trailers, nil
}

// Trailer is one Key: value line from a commit message's trailer block.
type Trailer struct {
	Key   string
	Value string
}

// String renders the trailer as it appears in a commit message.
func (t Trailer) String() string { return t.Key + ": " + t.Value }

// Package gitops models the GitOps repository: a cached, locked checkout of
// it, the directory layout that locates a component, and the two contract
// files (deploy.yaml and component.yaml) that describe what may be deployed
// where.
package gitops

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/git"
)

// Repository is a local clone of a GitOps repository, cached between runs and
// held under an exclusive lock for the duration of one.
type Repository struct {
	// Root is the checkout directory.
	Root string

	// URL is the remote this was cloned from.
	URL string

	// Branch is the remote's default branch, the branch deploys land on.
	Branch string

	Git git.Client

	lock *os.File
}

// RemoteName is the remote deploys read from and push to.
const RemoteName = "origin"

// Options configures Open.
type Options struct {
	// URL is the GitOps repository to clone. Required.
	URL string

	// Runner runs git. Defaults to ExecRunner.
	Runner command.Runner

	// CacheRoot overrides where checkouts are cached. Defaults to
	// <user cache dir>/intropy/gitops. Injectable so tests can redirect the
	// cache without reaching for HOME — on macOS os.UserCacheDir derives from
	// it, and overriding HOME makes every git invocation pay a multi-second
	// penalty for a home directory that does not match the passwd entry.
	CacheRoot string
}

// Open returns a clean, up-to-date checkout of the GitOps repository.
//
// The checkout is cached and reused across runs, so a deploy does not pay for a
// full clone every time. Because it is shared, three things are non-negotiable:
// an exclusive lock for the whole run, a hard reset rather than a merge on
// refresh, and removal of untracked files. A previous run killed part-way
// through an edit must not be able to leak that edit into this one's commit.
//
// The caller must Close the result.
func Open(ctx context.Context, opts Options) (*Repository, error) {
	if opts.URL == "" {
		return nil, errors.New("no GitOps repository URL")
	}
	r := opts.Runner
	if r == nil {
		r = command.ExecRunner{}
	}
	url := opts.URL

	cacheRoot := opts.CacheRoot
	if cacheRoot == "" {
		var err error
		if cacheRoot, err = defaultCacheRoot(); err != nil {
			return nil, err
		}
	}
	dir := CheckoutDir(cacheRoot, url)
	if err := os.MkdirAll(filepath.Dir(dir), 0o755); err != nil {
		return nil, fmt.Errorf("create cache directory: %w", err)
	}

	lock, err := acquireLock(dir + ".lock")
	if err != nil {
		return nil, err
	}

	wt := &Repository{Root: dir, URL: url, lock: lock}
	wt.Git = git.Client{Runner: r, Dir: dir}

	if err := wt.refresh(ctx, r); err != nil {
		wt.Close()
		return nil, err
	}
	return wt, nil
}

func (w *Repository) refresh(ctx context.Context, r command.Runner) error {
	if _, err := os.Stat(filepath.Join(w.Root, ".git")); err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("inspect %s: %w", w.Root, err)
		}
		// A directory without .git is the debris of an interrupted clone;
		// git clone refuses to write into it, so clear it first.
		if err := os.RemoveAll(w.Root); err != nil {
			return fmt.Errorf("clear %s: %w", w.Root, err)
		}
		if err := git.Clone(ctx, r, w.URL, w.Root); err != nil {
			return err
		}
	}

	branch, err := w.Git.DefaultBranch(ctx, RemoteName)
	if err != nil {
		return err
	}
	w.Branch = branch

	if err := w.Git.Fetch(ctx, RemoteName, branch); err != nil {
		return err
	}
	// Hard reset, not pull: the cache has no local history worth preserving,
	// and a merge could leave conflict markers in a file we are about to
	// commit.
	if err := w.Git.ResetHard(ctx, RemoteName+"/"+branch); err != nil {
		return err
	}
	return w.Git.Clean(ctx)
}

// Close releases the lock. The checkout itself is deliberately kept.
func (w *Repository) Close() error {
	if w.lock == nil {
		return nil
	}
	err := syscall.Flock(int(w.lock.Fd()), syscall.LOCK_UN)
	if cerr := w.lock.Close(); err == nil {
		err = cerr
	}
	w.lock = nil
	return err
}

func defaultCacheRoot() (string, error) {
	base, err := os.UserCacheDir()
	if err != nil {
		return "", fmt.Errorf("locate cache directory: %w", err)
	}
	return filepath.Join(base, "intropy", "gitops"), nil
}

// CachedRoot returns the existing cached checkout for the configured GitOps
// repository.
//
// It never clones or fetches. This backs shell completion, which has to be
// instant and must not touch the network — an unconfigured or not-yet-cloned
// repository simply yields no suggestions.
func CachedRoot(gitopsRepoOverride string) (string, error) {
	cfg, err := config.Load()
	if err != nil {
		return "", err
	}
	url, err := cfg.Resolve(config.Flags{GitopsRepo: gitopsRepoOverride}).RequireGitopsRepo()
	if err != nil {
		return "", err
	}
	cacheRoot, err := defaultCacheRoot()
	if err != nil {
		return "", err
	}
	dir := CheckoutDir(cacheRoot, url)
	if _, err := os.Stat(filepath.Join(dir, ".git")); err != nil {
		return "", fmt.Errorf("no cached checkout of %s yet", url)
	}
	return dir, nil
}

// CheckoutDir derives a stable cache path from the remote URL. The URL is
// hashed rather than sanitised because the same repository can be named several
// ways (SSH, HTTPS, with or without .git) and because URLs contain characters
// that are awkward in paths.
func CheckoutDir(cacheRoot, url string) string {
	sum := sha256.Sum256([]byte(url))
	return filepath.Join(cacheRoot, hex.EncodeToString(sum[:])[:16])
}

// acquireLock takes an exclusive, non-blocking lock. Non-blocking on purpose:
// two concurrent deploys sharing one checkout would interleave edits, and
// telling the user to wait is far better than silently queueing behind a run
// that may itself be stuck on a network operation.
func acquireLock(path string) (*os.File, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, fmt.Errorf("open lock file %s: %w", path, err)
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		f.Close()
		if errors.Is(err, syscall.EWOULDBLOCK) {
			return nil, fmt.Errorf("another intropy deploy is already using the cached GitOps checkout (%s); wait for it to finish", filepath.Dir(path))
		}
		return nil, fmt.Errorf("lock %s: %w", path, err)
	}
	return f, nil
}

// Package deploy orchestrates a deployment: it resolves which image digest a
// commit produced, pins it into one environment's overlay in the GitOps
// repository, and reports what changed.
//
// The mechanics live in narrower packages — command, git, gitops, kustomize,
// registry, release and source — and this package is the policy that combines
// them.
package deploy

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/integrio-intropy/intropy-cli/internal/argocd"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
)

// Run resolves the digests to deploy — from a release manifest when Version is
// set, otherwise from the current commit — and pins them into one
// environment's overlay.
//
// With PlanOnly set it stops after the diff, having written nothing. Otherwise
// it commits, pushes, and waits for ArgoCD to converge unless the environment
// syncs manually or NoWait is set.
func Run(ctx context.Context, opts Options) error {
	opts.applyDefaults()

	s, err := openSession(ctx, opts.session(), "git", "kustomize")
	if err != nil {
		return err
	}
	defer s.Close()
	repo, deployCfg := s.repo, s.deployCfg

	env, err := deployCfg.Environment(opts.Environment)
	if err != nil {
		return err
	}

	coord, comp, err := s.locateComponent(opts.Component, opts.Domain, opts.System)
	if err != nil {
		return err
	}
	if err := requirePinnable(coord, comp); err != nil {
		return err
	}
	overlayDir, err := gitops.ResolveOverlay(repo.Root, coord, comp, opts.Environment)
	if err != nil {
		return err
	}

	org, err := resolveOrigin(ctx, opts, coord, comp)
	if err != nil {
		return err
	}

	out := opts.output()
	plan, err := BuildPlan(ctx, PlanOptions{
		Repository:     repo,
		Kustomize:      kustomize.Client{Runner: opts.Runner},
		Coordinate:     coord,
		Environment:    opts.Environment,
		Source:         org.State,
		ReleaseVersion: org.ReleaseVersion(),
		Pins:           org.Pins,
		Upstreams:      InspectUpstreams(repo.Root, coord, comp, opts.Environment, env, org.Pins),
		OverlayDir:     overlayDir,
		Palette:        out.palette(),
	})
	if err != nil {
		return err
	}

	// An empty plan already reverted itself, and --plan must leave no trace, so
	// only the apply path proceeds past here.
	if plan.Empty() || opts.PlanOnly {
		if opts.PlanOnly && !plan.Empty() {
			defer revertOverlay(ctx, out, plan, repo)
		}
		return report(out, plan, coord, env, "", nil)
	}

	// Print the plan before writing anything, so the diff is on screen even if
	// the push then fails. Not in JSON mode: there the encoded result is the
	// program output, and a diff on the same stream would make it unparseable.
	if out.Format == OutputPlain {
		reportPlan(out, plan)
	}

	revision, err := Publish(ctx, PublishOptions{
		Repository: repo,
		Plan:       plan,
		CliVersion: opts.UserAgent,
		Stderr:     opts.Stderr,
	})
	if err != nil {
		// Publish leaves nothing pushed on failure, but the local commit may
		// exist; the checkout is hard-reset on the next run either way.
		return err
	}
	fmt.Fprintf(opts.Stderr, "pushed %s to %s\n", git.ShortSHA(revision), repo.Branch)

	// A manual-sync environment is gated in ArgoCD, so there is no sync to wait
	// for; --no-wait opts out everywhere else.
	if opts.NoWait || env.Sync == gitops.SyncManual {
		return report(out, plan, coord, env, revision, nil)
	}

	app, observed, err := WaitForSync(ctx, WaitOptions{
		Repository:   repo,
		DeployCfg:    deployCfg,
		AppName:      coord.AppName(opts.Environment),
		Revision:     revision,
		Timeout:      opts.Timeout,
		ArgocdServer: opts.ArgocdServer,
		ConfigServer: s.argocdServer,
		UserAgent:    opts.UserAgent,
		Stderr:       opts.Stderr,
	})
	if err != nil {
		return err
	}
	if !observed {
		app = nil
	}
	return report(out, plan, coord, env, revision, app)
}

func componentDir(root string, c gitops.Coordinate) string {
	return gitops.JoinRel(root, c.RelPath())
}

// revertOverlay discards the plan's overlay edits, warning if it cannot. The
// cached checkout is shared between runs, so leaving it dirty would poison the
// next one.
func revertOverlay(ctx context.Context, out output, plan *Plan, repo *gitops.Repository) {
	if err := plan.Revert(ctx, repo); err != nil {
		fmt.Fprintf(out.Stderr, "warning: could not revert the overlay edit: %v\n", err)
	}
}

// reportPlan writes the human summary and diff to stdout.
func reportPlan(out output, plan *Plan) {
	fmt.Fprint(out.Stdout, plan.Summary())
	if plan.ProvenanceOnly() {
		// kustomize propagates commonAnnotations into pod templates, so this
		// still restarts the pods. Say so rather than let it surprise anyone.
		fmt.Fprintf(out.Stdout, "\nno image digest changed; only the source-commit annotation moves.\nthis still restarts the pods, because kustomize applies commonAnnotations to pod templates.\n")
	}
	fmt.Fprintf(out.Stdout, "\n%s", plan.Diff)
}

// report writes the final outcome. revision is the pushed sha, empty when
// nothing was pushed.
func report(out output, plan *Plan, coord gitops.Coordinate, env gitops.EnvironmentConfig, revision string, app *argocd.Application) error {
	if out.Format == OutputJSON {
		return writeJSON(out, plan, coord, env, revision, app)
	}

	// Already there. Still print the upstream comparison: "staging is already
	// running the digest dev tested" is the most reassuring form of this
	// message, and suppressing it would withhold the answer to the question
	// that prompted the command.
	if plan.Empty() {
		fmt.Fprintf(out.Stdout, "%s is already at %s in %s; nothing to do\n",
			coord, plan.pinnedAs(), plan.Environment)
		fmt.Fprint(out.Stdout, plan.noteLines())
		return nil
	}

	if revision == "" {
		reportPlan(out, plan)
		fmt.Fprintf(out.Stderr, "\nplan only: nothing was committed\n")
		return nil
	}

	// A manual-sync environment is gated in ArgoCD, so the commit is as far as
	// a deploy can take it. Waiting would hang on a sync that never starts.
	if env.Sync == gitops.SyncManual {
		// Both commands, and the sha --revision wants. The gate is a second person
		// reading the rendered change, and telling them only the command to apply it
		// leaves them to find the revision they are approving for themselves.
		fmt.Fprintf(out.Stdout, "\ncommitted %s to %s. %s syncs manually, so nothing is applied yet:\n"+
			"  intropy deploy diff %s --env %s\n"+
			"  intropy deploy sync %s --env %s --revision %s\n",
			git.ShortSHA(revision), plan.Environment, plan.Environment,
			coord.Component, plan.Environment,
			coord.Component, plan.Environment, revision)
		return nil
	}

	if app != nil {
		fmt.Fprintf(out.Stdout, "\ncommitted %s; %s is synced and healthy at %s\n",
			git.ShortSHA(revision), coord.AppName(plan.Environment), shortDigest(app.Status.Sync.Revision))
		return nil
	}
	fmt.Fprintf(out.Stdout, "\ncommitted %s; ArgoCD will sync %s\n", git.ShortSHA(revision), coord.AppName(plan.Environment))
	return nil
}

func writeJSON(out output, plan *Plan, coord gitops.Coordinate, env gitops.EnvironmentConfig, revision string, app *argocd.Application) error {
	res := Result{
		Component:    coord.Component,
		Domain:       coord.Domain,
		System:       coord.System,
		Environment:  plan.Environment,
		SourceCommit: plan.Source.Commit,
		AppName:      coord.AppName(plan.Environment),
		OverlayPath:  coord.OverlayRelPath(plan.Environment),
		Changed:      !plan.Empty(),
		Applied:      revision != "",
		Revision:     revision,
		Upstreams:    plan.Upstreams,
		SyncPolicy:   env.Sync,
	}
	res.Release = plan.ReleaseVersion
	res.PromotedFrom = plan.PromotedFrom
	if app != nil {
		res.SyncStatus = app.Status.Sync.Status
		res.HealthStatus = app.Status.Health.Status
		res.SyncedRevision = app.Status.Sync.Revision
	}
	for _, pin := range plan.Pins {
		res.Pins = append(res.Pins, ResultPin{
			Image:    pin.Image,
			Previous: plan.Previous[pin.Image],
			Digest:   pin.Digest,
			Tag:      pin.Tag,
		})
	}

	enc := json.NewEncoder(out.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(res); err != nil {
		return fmt.Errorf("write JSON result: %w", err)
	}
	return nil
}

package deploy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"math/rand/v2"
	"os"
	"strings"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
)

// Trailer keys written into the deployment commit. They are a format, not just
// a message: `deploy history` reads them back, so treat renames as breaking.
const (
	TrailerComponent   = "Deploy-Component"
	TrailerDomain      = "Deploy-Domain"
	TrailerSystem      = "Deploy-System"
	TrailerEnvironment = "Deploy-Env"

	// TrailerRelease is present only when the deployment came from a published
	// release, so `deploy history` can answer "which version is in staging"
	// from one trailer.
	TrailerRelease = "Deploy-Release"

	// TrailerPromotedFrom names the environment the digests were copied from,
	// present only for a promotion. It is what distinguishes a promotion from a
	// deployment in the log: both edit the same file the same way, and the
	// subject alone cannot say which resolved its digests and which copied them.
	TrailerPromotedFrom = "Deploy-Promoted-From"

	TrailerImage        = "Deploy-Image"
	TrailerDigest       = "Deploy-Digest"
	TrailerSourceCommit = "Deploy-Source-Commit"
	TrailerBy           = "Deploy-By"
	TrailerCli          = "Deploy-Cli"
)

// maxPushAttempts bounds the rebase-and-retry loop. A one-line change to one
// file replays cleanly, so exhausting this many attempts means the environment
// is being deployed to continuously rather than that the retry is broken.
const maxPushAttempts = 5

// PublishOptions configures Publish.
type PublishOptions struct {
	Repository *gitops.Repository
	Plan       *Plan

	// CliVersion is recorded in a trailer so a bad deploy can be traced to the
	// version that produced it.
	CliVersion string

	// MaxAttempts defaults to maxPushAttempts.
	MaxAttempts int

	// Backoff returns how long to wait before the given attempt (1-based).
	// Defaults to jittered exponential.
	Backoff func(attempt int) time.Duration

	// Sleep defaults to time.Sleep; tests replace it to avoid real delays.
	Sleep func(time.Duration)

	Stderr io.Writer
}

func (o *PublishOptions) applyDefaults() {
	if o.MaxAttempts <= 0 {
		o.MaxAttempts = maxPushAttempts
	}
	if o.Backoff == nil {
		o.Backoff = jitteredBackoff
	}
	if o.Sleep == nil {
		o.Sleep = time.Sleep
	}
	if o.Stderr == nil {
		o.Stderr = io.Discard
	}
}

// Publish commits the overlay change and pushes it, rebasing and retrying if
// someone else pushed first.
//
// It returns the sha that actually landed on the remote. That is not necessarily
// the sha of the first commit: a rebase rewrites it, and every later step — the
// ArgoCD revision gate above all — must reason about the final one.
func Publish(ctx context.Context, opts PublishOptions) (string, error) {
	opts.applyDefaults()

	repo := opts.Repository
	plan := opts.Plan
	rel := plan.RelKustomizationPath(repo.Root)

	// Stage only the file the plan changed. A blanket `git add -A` in a shared
	// checkout would sweep up anything else that happened to be there.
	if err := repo.Git.Add(ctx, rel); err != nil {
		return "", err
	}
	if err := repo.Git.Commit(ctx, commitSubject(plan), commitTrailers(plan, opts.CliVersion)); err != nil {
		return "", err
	}

	refspec := "HEAD:" + repo.Branch
	remoteRef := gitops.RemoteName + "/" + repo.Branch

	for attempt := 1; ; attempt++ {
		err := repo.Git.Push(ctx, gitops.RemoteName, refspec)
		if err == nil {
			return repo.Git.HEAD(ctx)
		}

		var rejected *git.PushRejectedError
		if !errors.As(err, &rejected) {
			// Authentication, network, a missing remote: retrying cannot help.
			return "", err
		}
		if attempt >= opts.MaxAttempts {
			return "", fmt.Errorf("gave up after %d push attempt%s: %s is being deployed to concurrently — try again",
				opts.MaxAttempts, plural(opts.MaxAttempts), repo.Branch)
		}

		fmt.Fprintf(opts.Stderr, "push rejected; rebasing onto %s and retrying (%d/%d)\n", remoteRef, attempt+1, opts.MaxAttempts)
		opts.Sleep(opts.Backoff(attempt))

		if err := repo.Git.Fetch(ctx, gitops.RemoteName, repo.Branch); err != nil {
			return "", err
		}
		if err := repo.Git.Rebase(ctx, remoteRef); err != nil {
			var conflict *git.RebaseConflictError
			if !errors.As(err, &conflict) {
				return "", err
			}
			// A conflict here means someone deployed the *same component to the
			// same environment* in the same moment, so both commits edit the
			// same line. Auto-resolving would silently pick a winner and
			// discard a deployment someone believes succeeded.
			if abortErr := repo.Git.RebaseAbort(ctx); abortErr != nil {
				return "", fmt.Errorf("%w (and the rebase could not be aborted: %v)", err, abortErr)
			}
			return "", fmt.Errorf("another deployment of %s to %s landed at the same moment, and the two changes conflict.\nNothing was pushed. Re-run to deploy on top of theirs",
				plan.Coordinate, plan.Environment)
		}
	}
}

// commitSubject is the one-line summary. The digest is abbreviated: a full one
// makes the subject unreadable in a log, and the trailer carries it in full.
//
// A release deploy names the version instead of the digest. A release is
// immutable, so the version identifies those digests exactly and is the more
// useful thing to read in a log; the trailers still carry every digest in full.
//
// The prefix is deploy() for a promotion too. A promotion makes the same edit to
// the same file, so calling it something else in the subject would split one
// history in two; TrailerPromotedFrom is what tells them apart.
func commitSubject(plan *Plan) string {
	component, env, commit := plan.Coordinate.Component, plan.Environment, plan.Source.ShortCommit()

	if plan.ReleaseVersion != "" {
		// Both versions known: the far more useful subject, and the only one that
		// says what a promotion actually did.
		if plan.PreviousRelease != "" && plan.PreviousRelease != plan.ReleaseVersion {
			return fmt.Sprintf("deploy(%s): %s %s → %s", component, env, plan.PreviousRelease, plan.ReleaseVersion)
		}
		if len(plan.Pins) > 1 {
			return fmt.Sprintf("deploy(%s): %s → %s, %d images (%s)", component, env, plan.ReleaseVersion, len(plan.Pins), commit)
		}
		return fmt.Sprintf("deploy(%s): %s → %s (%s)", component, env, plan.ReleaseVersion, commit)
	}

	if len(plan.Pins) > 1 {
		return fmt.Sprintf("deploy(%s): %s → %d images at %s", component, env, len(plan.Pins), commit)
	}
	return fmt.Sprintf("deploy(%s): %s → %s (%s)", component, env, shortDigest(plan.Pins[0].Digest), commit)
}

func shortDigest(digest string) string {
	const prefix = "sha256:"
	if hex, ok := strings.CutPrefix(digest, prefix); ok && len(hex) > 12 {
		return prefix + hex[:12]
	}
	return digest
}

// commitTrailers builds the trailer block: one paragraph, one Key: value per
// line, which is what makes it machine-readable by `git log --format=%(trailers)`.
func commitTrailers(plan *Plan, cliVersion string) string {
	trailers := []git.Trailer{
		{Key: TrailerComponent, Value: plan.Coordinate.Component},
		{Key: TrailerDomain, Value: plan.Coordinate.Domain},
		{Key: TrailerSystem, Value: plan.Coordinate.System},
		{Key: TrailerEnvironment, Value: plan.Environment},
	}
	// What was deployed where, before the per-image detail.
	if plan.ReleaseVersion != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerRelease, Value: plan.ReleaseVersion})
	}
	if plan.PromotedFrom != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerPromotedFrom, Value: plan.PromotedFrom})
	}
	for _, pin := range plan.Pins {
		trailers = append(trailers,
			git.Trailer{Key: TrailerImage, Value: pin.Image},
			git.Trailer{Key: TrailerDigest, Value: pin.Digest},
		)
	}
	trailers = append(trailers, git.Trailer{Key: TrailerSourceCommit, Value: plan.Source.Commit})
	if who := committer(); who != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerBy, Value: who})
	}
	if cliVersion != "" {
		trailers = append(trailers, git.Trailer{Key: TrailerCli, Value: cliVersion})
	}

	var b []byte
	for i, t := range trailers {
		if i > 0 {
			b = append(b, '\n')
		}
		b = append(b, t.String()...)
	}
	return string(b)
}

// committer identifies who ran the deploy, beyond git's own author fields: in
// CI the git identity is often a service account, so the environment is a
// better signal when it is set.
func committer() string {
	for _, key := range []string{"GITLAB_USER_EMAIL", "GITHUB_ACTOR", "USER"} {
		if v := os.Getenv(key); v != "" {
			return v
		}
	}
	return ""
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

// jitteredBackoff grows the delay and spreads concurrent retries apart, so two
// deploys that collide do not keep colliding in lockstep.
func jitteredBackoff(attempt int) time.Duration {
	base := 100 * time.Millisecond * (1 << min(attempt-1, 4))
	return base + rand.N(base)
}

package deploy

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// The templates deploy init renders. They are separate packages because they
// render a different number of times — once per system, once per component —
// into different directories, from different value sets.
const (
	TemplateDeployHost      = "deploy-host"
	TemplateDeployComponent = "deploy-component"
)

// HostDirName is the component directory holding a system's shared manifests.
//
// A Dapr Component is namespace-scoped and every integration in a customer's
// namespace shares it, so exactly one ArgoCD Application may own each one. The
// system host is what gives them that owner: it has no Dockerfile and therefore
// no image, which is precisely what gitops.KindShared describes.
const HostDirName = "host"

// initBranchPrefix namespaces the branches this command pushes.
const initBranchPrefix = "deploy-init/"

// runGraph is the seam tests replace to avoid a dotnet build.
var runGraph = topology.RunGraph

// InitOptions configures Init.
//
// There is no Environment: overlays are created for every environment the
// repository defines unless Environments narrows it. There is no AllowDirty, no
// NoWait and no Timeout either — no source working tree is read for correctness,
// and nothing is synced.
type InitOptions struct {
	// Components narrows the run to named topology components. Empty means the
	// whole system, host included.
	Components []string

	// Domain places the system in the GitOps tree. Unlike every other deploy
	// subcommand's --domain this is a destination rather than a filter. Empty is
	// inferred when exactly one domain already holds the system.
	Domain string

	// System overrides the topology's own system name as the tree segment.
	System string

	// Environments selects which overlays to create. Empty means every
	// environment in deploy.yaml.
	Environments []string

	// TopologyFile reads the record from a file instead of running the host's
	// graph verb; "-" reads stdin. Both the CI path and the test seam.
	TopologyFile string

	// SourceDir is where system hosts and scaffold records are discovered.
	SourceDir string

	// TemplateVersion pins the template library release.
	TemplateVersion string

	// Files, SetValues, NoInput and Stdin are the value layering, identical to
	// int create.
	Files     []string
	SetValues map[string]any
	NoInput   bool
	Stdin     io.Reader

	// PlanOnly resolves, renders and classifies, then reports without writing
	// anything or touching git.
	PlanOnly bool

	// Force overwrites files that already differ, subject to the pinned-digest
	// guard in assertForceIsSafe.
	Force bool

	GitopsRepo   string
	OutputFormat string
	Color        bool
	CacheRoot    string

	Runner     command.Runner
	UserAgent  string
	CliVersion string
	Stdout     io.Writer
	Stderr     io.Writer

	// Test overrides for the template library. Production callers leave these
	// zero-valued.
	Owner         string
	Repo          string
	GitHubBaseURL string
	HTTP          *http.Client
}

func (o InitOptions) output() output {
	return output{Format: o.OutputFormat, Color: o.Color, Stdout: o.Stdout, Stderr: o.Stderr}
}

func (o InitOptions) session() sessionOptions {
	return sessionOptions{
		GitopsRepo: o.GitopsRepo,
		CacheRoot:  o.CacheRoot,
		Runner:     o.Runner,
		Stderr:     o.Stderr,
	}
}

func (o *InitOptions) applyDefaults() {
	if o.Runner == nil {
		o.Runner = command.ExecRunner{}
	}
	if o.SourceDir == "" {
		o.SourceDir = "."
	}
	if o.OutputFormat == "" {
		o.OutputFormat = OutputPlain
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
}

// Init scaffolds a system's manifests into the GitOps repository.
//
// The sequencing matters more than it looks. The topology is resolved *before*
// the session is opened, because openSession takes a non-blocking exclusive lock
// on the shared cached checkout and the graph verb can take minutes on a cold
// project — holding the lock across that would fail every colleague's deploy
// outright. Nothing is written until every file has been classified, and nothing
// is pushed to the default branch: a tree full of placeholders would be picked up
// by the ApplicationSet immediately.
func Init(ctx context.Context, opts InitOptions) error {
	opts.applyDefaults()
	out := opts.output()

	topo, scaffolds, err := resolveInitTopology(ctx, opts)
	if err != nil {
		return err
	}

	s, err := openSession(ctx, opts.session(), "git")
	if err != nil {
		return err
	}
	defer s.Close()

	facts, err := newInitFacts(opts, s, topo, scaffolds)
	if err != nil {
		return err
	}

	staging, err := os.MkdirTemp("", "intropy-deploy-init-*")
	if err != nil {
		return fmt.Errorf("create staging directory: %w", err)
	}
	defer os.RemoveAll(staging)

	libraryRef, err := renderScaffold(ctx, opts, facts, staging)
	if err != nil {
		return err
	}
	branch := initBranchPrefix + facts.Domain + "-" + facts.System

	rels, err := stageRels(staging)
	if err != nil {
		return err
	}
	actions, err := classifyStaged(staging, s.repo.Root, rels, opts.Force)
	if err != nil {
		return err
	}
	if opts.Force {
		if err := assertForceIsSafe(s.repo.Root, actions); err != nil {
			return err
		}
	}

	result := InitResult{
		System:       facts.System,
		Domain:       facts.Domain,
		Host:         HostDirName,
		Template:     libraryRef,
		Components:   facts.ComponentNames(),
		Files:        actions,
		Applied:      false,
		Placeholders: nil,
	}

	if opts.PlanOnly {
		// Scan the staging tree: the files are not in the repository yet, so the
		// only place the placeholders exist is where they were rendered.
		result.Placeholders, err = scanPlaceholders(staging, rels)
		if err != nil {
			return err
		}
		return reportInit(out, result, actions, true)
	}

	if writes(actions) == 0 {
		// Nothing to write, but the placeholders already in the repository are
		// still the answer to "what is left to do here".
		result.Placeholders, err = scanPlaceholders(s.repo.Root, rels)
		if err != nil {
			return err
		}
		return reportInit(out, result, actions, false)
	}

	published, err := publishScaffold(ctx, opts, s.repo, publishScaffoldOptions{
		StagingDir: staging,
		Actions:    actions,
		Rels:       rels,
		Branch:     branch,
		Facts:      facts,
	})
	if err != nil {
		return err
	}
	result.Applied = true
	result.Branch = branch
	result.Revision = published.Revision
	result.Placeholders = published.Placeholders

	return reportInit(out, result, actions, false)
}

func writes(actions []FileAction) int {
	n := 0
	for _, a := range actions {
		if a.Writes() {
			n++
		}
	}
	return n
}

// resolveInitTopology obtains the record and the workspace's scaffold records.
//
// A file beats the graph verb: it is how CI avoids paying for a dotnet build, and
// how tests avoid needing dotnet at all.
func resolveInitTopology(ctx context.Context, opts InitOptions) (*topology.Topology, []template.ScaffoldEntry, error) {
	scaffolds, warnings := template.ListScaffolds(opts.SourceDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}

	if opts.TopologyFile != "" {
		r := opts.Stdin
		if opts.TopologyFile != "-" {
			f, err := os.Open(opts.TopologyFile)
			if err != nil {
				return nil, nil, fmt.Errorf("read --topology: %w", err)
			}
			defer f.Close()
			r = f
		}
		topo, err := topology.Decode(r)
		if err != nil {
			return nil, nil, fmt.Errorf("read --topology %s: %w", opts.TopologyFile, err)
		}
		return topo, scaffolds, nil
	}

	var hosts []template.ScaffoldEntry
	for _, s := range scaffolds {
		if s.Role == template.RoleSystemHost {
			hosts = append(hosts, s)
		}
	}
	switch len(hosts) {
	case 0:
		return nil, nil, fmt.Errorf("no system host found under %s; run this from a system workspace, or pass --topology with the output of `dotnet run --project <host> -- graph`", opts.SourceDir)
	case 1:
	default:
		names := make([]string, 0, len(hosts))
		for _, h := range hosts {
			names = append(names, h.Path)
		}
		slices.Sort(names)
		return nil, nil, fmt.Errorf("%s holds %d system hosts (%s); use -C to pick one, or pass --topology",
			opts.SourceDir, len(hosts), strings.Join(names, ", "))
	}

	// Said before starting, not after: a silent multi-minute wait reads as a hang.
	fmt.Fprintf(opts.Stderr, "reading topology from %s (building first; this can take a minute)\n", hosts[0].Path)
	topo, err := runGraph(ctx, hosts[0].Path)
	if err != nil {
		return nil, nil, fmt.Errorf("%s: %w", hosts[0].Path, err)
	}
	return topo, scaffolds, nil
}

// initFacts is everything derived before rendering: where the manifests go, what
// the platform is, and the model the skeletons range over.
type initFacts struct {
	Domain string
	System string

	Environments []string
	Registry     string
	AppNamespace string
	Platform     gitops.PlatformConfig

	Model     InitModel
	Scaffolds map[string]template.ScaffoldEntry
	Selected  []InitComponent
}

func (f initFacts) ComponentNames() []string {
	names := make([]string, 0, len(f.Selected))
	for _, c := range f.Selected {
		names = append(names, c.Name)
	}
	return names
}

func newInitFacts(opts InitOptions, s *session, topo *topology.Topology, scaffolds []template.ScaffoldEntry) (initFacts, error) {
	system := opts.System
	if system == "" {
		system = topo.System
	}
	if system == "" {
		return initFacts{}, fmt.Errorf("the topology record names no system; pass --system")
	}

	domain, err := resolveInitDomain(s.repo.Root, opts.Domain, system)
	if err != nil {
		return initFacts{}, err
	}

	environments, err := selectEnvironments(s.deployCfg, opts.Environments)
	if err != nil {
		return initFacts{}, err
	}

	model := newInitModel(topo, scaffolds)
	selected, err := selectComponents(model, opts.Components)
	if err != nil {
		return initFacts{}, err
	}
	for _, c := range selected {
		if c.Dir == "" {
			fmt.Fprintf(opts.Stderr, "warning: %s has no scaffold record under %s; its manifests will be generated without an appId or sourcePaths\n", c.Name, opts.SourceDir)
		}
	}

	return initFacts{
		Domain:       domain,
		System:       system,
		Environments: environments,
		Registry:     s.deployCfg.Registry,
		AppNamespace: s.deployCfg.Argocd.AppNamespace,
		Platform:     s.deployCfg.Platform,
		Model:        model,
		Scaffolds:    matchScaffolds(topo.Components, scaffolds),
		Selected:     selected,
	}, nil
}

// resolveInitDomain places the system in the tree.
//
// The topology has no idea which business domain a system belongs to, so on a
// first run the domain has to be given. Afterwards it is inferred, which is what
// makes a re-run flag-free — the common case.
func resolveInitDomain(root, flag, system string) (string, error) {
	if flag != "" {
		return flag, nil
	}
	var found []string
	for _, c := range gitops.ListComponents(root) {
		if c.System == system && !slices.Contains(found, c.Domain) {
			found = append(found, c.Domain)
		}
	}
	slices.Sort(found)
	switch len(found) {
	case 1:
		return found[0], nil
	case 0:
		return "", fmt.Errorf("--domain is required: %s is not in the repository yet, so there is no domain to infer", system)
	default:
		return "", fmt.Errorf("--domain is required: %s exists under %s", system, strings.Join(found, " and "))
	}
}

func selectEnvironments(cfg *gitops.DeployConfig, requested []string) ([]string, error) {
	if len(requested) == 0 {
		// Every environment, in promotion order. The ApplicationSet takes the
		// environment from its cluster generator rather than the path, so an
		// environment without an overlay is an Application pointing at nothing.
		return cfg.PromotionOrder(), nil
	}
	for _, env := range requested {
		if _, err := cfg.Environment(env); err != nil {
			return nil, err
		}
	}
	out := slices.Clone(requested)
	slices.Sort(out)
	return slices.Compact(out), nil
}

func selectComponents(m InitModel, requested []string) ([]InitComponent, error) {
	if len(requested) == 0 {
		return m.Components, nil
	}
	byName := make(map[string]InitComponent, len(m.Components))
	names := make([]string, 0, len(m.Components))
	for _, c := range m.Components {
		byName[c.Name] = c
		names = append(names, c.Name)
	}
	var out []InitComponent
	for _, want := range requested {
		c, ok := byName[want]
		if !ok {
			return nil, fmt.Errorf("no component %q in the topology; it declares: %s", want, strings.Join(names, ", "))
		}
		out = append(out, c)
	}
	slices.SortFunc(out, func(a, b InitComponent) int { return strings.Compare(a.Name, b.Name) })
	return out, nil
}

// renderScaffold renders the host template once and the component template once
// per selected component, into a staging tree that mirrors the repository root.
//
// Staging mirrors the repository so a staged path is already the repo-relative
// path the classifier and the commit both need.
// It returns the resolved library reference so the result can record which
// release produced the tree a reviewer is looking at.
func renderScaffold(ctx context.Context, opts InitOptions, facts initFacts, staging string) (string, error) {
	lib, err := template.FetchLibrary(ctx, template.LibraryOptions{
		Version:       opts.TemplateVersion,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Stderr:        opts.Stderr,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		GitHubBaseURL: opts.GitHubBaseURL,
	})
	if err != nil {
		return "", err
	}
	defer lib.Close()

	if err := renderOne(opts, facts, lib, TemplateDeployHost, HostDirName, nil, staging); err != nil {
		return "", err
	}
	for _, c := range facts.Selected {
		comp := c
		if err := renderOne(opts, facts, lib, TemplateDeployComponent, c.Name, &comp, staging); err != nil {
			return "", err
		}
	}
	return lib.Ref(), nil
}

// renderOne renders one unit — the host, or one component — into the staging
// tree.
//
// The skeleton is rendered once per environment, because the renderer templates
// paths but does not iterate them, so `overlays/{{ .env }}/kustomization.yaml` is
// the only way to get one directory per environment. mergeRendered then enforces
// that everything outside overlays/ came out identical on every pass.
func renderOne(opts InitOptions, facts initFacts, lib *template.Library, templateName, dirName string, comp *InitComponent, staging string) error {
	tmpl, skeleton, err := lib.Open(templateName)
	if err != nil {
		return err
	}

	dest := filepath.Join(staging, filepath.FromSlash(componentRelPath(facts.Domain, facts.System, dirName)))
	if err := os.MkdirAll(dest, 0o755); err != nil {
		return err
	}

	for _, env := range facts.Environments {
		values, err := resolveInitValues(opts, facts, tmpl, dirName, comp, env)
		if err != nil {
			return fmt.Errorf("%s for %s: %w", templateName, dirName, err)
		}

		pass, err := os.MkdirTemp("", "intropy-render-*")
		if err != nil {
			return err
		}
		err = template.RenderFiltered(skeleton, pass, values, tmpl.Spec.Files)
		if err == nil {
			err = mergeRendered(pass, dest, env)
		}
		os.RemoveAll(pass)
		if err != nil {
			return fmt.Errorf("render %s for %s (%s): %w", templateName, dirName, env, err)
		}
	}
	return nil
}

// resolveInitValues layers the derived facts under the user's input, then injects
// the structures spec.parameters cannot describe.
//
// Facts beat schema defaults; the user beats facts. That order is the whole point
// of ResolveLayered, and this is its first production caller.
func resolveInitValues(opts InitOptions, facts initFacts, tmpl *template.Template, dirName string, comp *InitComponent, env string) (map[string]any, error) {
	base := seedDeclaredParams(tmpl, initSeeds(facts, dirName, comp))

	prompter := template.AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
	values, err := template.ResolveLayered(tmpl, base, opts.Files, opts.Stdin, opts.SetValues, prompter)
	if err != nil {
		return nil, err
	}

	model, err := facts.Model.asMap()
	if err != nil {
		return nil, err
	}
	reserved := map[string]any{
		template.ReservedEnvKey:      env,
		template.ReservedTopologyKey: model,
		template.ReservedGitopsKey:   facts.gitopsMap(dirName, env),
	}
	if comp != nil {
		componentMap, err := toMap(comp)
		if err != nil {
			return nil, err
		}
		reserved[template.ReservedComponentKey] = componentMap
		reserved[template.ReservedScaffoldKey] = facts.scaffoldValues(comp.Name)
	}
	if err := template.InjectReserved(tmpl, values, reserved); err != nil {
		return nil, err
	}
	return values, nil
}

// initSeeds is every fact the CLI can derive, keyed by the parameter name a
// template would declare for it.
func initSeeds(facts initFacts, dirName string, comp *InitComponent) map[string]any {
	seeds := map[string]any{
		"domain":             facts.Domain,
		"system":             facts.System,
		"hostName":           HostDirName,
		"registry":           facts.Registry,
		"argocdAppNamespace": facts.AppNamespace,
		"provider":           facts.Platform.Provider,
		"pubsub":             facts.Platform.Pubsub,
		"secretStore":        facts.Platform.SecretStore,
	}
	// Only when unambiguous. Guessing between two brokers would put the wrong
	// name in a Component that the generated C# then fails to resolve.
	if len(facts.Model.PubSubs) == 1 {
		seeds["pubsubName"] = facts.Model.PubSubs[0].Name
	}
	if comp != nil {
		seeds["name"] = comp.Name
		seeds["kind"] = comp.Kind
		seeds["appId"] = comp.AppID
		seeds["workload"] = comp.Workload
		if comp.Dir != "" {
			seeds["sourceDir"] = comp.Dir
		}
	} else {
		seeds["name"] = dirName
		seeds["appId"] = dirName
	}
	return seeds
}

// seedDeclaredParams keeps only the seeds the template declares as parameters.
//
// An undeclared key would sail past JSON Schema validation and land in the value
// map anyway, which is how a template silently acquires a dependency nobody
// documented.
func seedDeclaredParams(tmpl *template.Template, seeds map[string]any) map[string]any {
	base := make(map[string]any, len(seeds))
	for _, f := range tmpl.Fields() {
		if v, ok := seeds[f.Name]; ok && !isBlank(v) {
			base[f.Name] = v
		}
	}
	return base
}

// isBlank drops an empty derived fact so the template's own default still
// applies: an unset platform.pubsub must not override `default: rabbitmq`.
func isBlank(v any) bool {
	s, ok := v.(string)
	return ok && s == ""
}

func (f initFacts) gitopsMap(component, env string) map[string]any {
	return map[string]any{
		"domain":             f.Domain,
		"system":             f.System,
		"component":          component,
		"env":                env,
		"host":               HostDirName,
		"registry":           f.Registry,
		"argocdAppNamespace": f.AppNamespace,
		"environments":       f.Environments,
		"platform": map[string]any{
			"provider":    f.Platform.Provider,
			"pubsub":      f.Platform.Pubsub,
			"secretStore": f.Platform.SecretStore,
		},
	}
}

// scaffoldValues is the component's recorded template values, or an empty map so
// a skeleton reading .scaffold.x never fails on a missing record.
func (f initFacts) scaffoldValues(component string) map[string]any {
	if s, ok := f.Scaffolds[component]; ok && s.Values != nil {
		return s.Values
	}
	return map[string]any{}
}

