package deploy

import (
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
)

// What scaffolding does to one file.
const (
	// ActionCreate: the file is not in the repository yet.
	ActionCreate = "create"

	// ActionIdentical: already there, byte for byte. Not written, and not
	// counted as a change — this is what makes a re-run a genuine no-op.
	ActionIdentical = "identical"

	// ActionSkipExists: already there and different. Left alone, because a
	// human or a previous deploy owns it now. Reported so the difference is
	// visible rather than silently ignored.
	ActionSkipExists = "skip-exists"

	// ActionOverwrite: already there and different, and --force was given.
	ActionOverwrite = "overwrite"
)

// FileAction is one staged file's fate.
type FileAction struct {
	// Rel is relative to the repository root, slash-separated.
	Rel    string `json:"path"`
	Action string `json:"action"`
}

// Writes reports whether the action puts bytes on disk.
func (a FileAction) Writes() bool {
	return a.Action == ActionCreate || a.Action == ActionOverwrite
}

// stageRels lists every file a render produced, relative to the staging root and
// slash-separated, sorted so a plan reads in tree order.
func stageRels(stagingDir string) ([]string, error) {
	var rels []string
	err := filepath.WalkDir(stagingDir, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(stagingDir, p)
		if err != nil {
			return err
		}
		rels = append(rels, filepath.ToSlash(rel))
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("read staged manifests: %w", err)
	}
	slices.Sort(rels)
	return rels, nil
}

// classifyStaged decides what to do with each staged file, given what is already
// in the repository.
//
// Rendering straight into the tree is never an option: the renderer overwrites,
// and an overlay holds digests intropy deploy pinned. Staging first and
// classifying second is what makes this command additive — a system gains a
// component and only that subtree is new, while everything a human has since
// edited is left exactly as it is.
func classifyStaged(stagingDir, destRoot string, rels []string, force bool) ([]FileAction, error) {
	actions := make([]FileAction, 0, len(rels))
	for _, rel := range rels {
		staged := filepath.Join(stagingDir, filepath.FromSlash(rel))
		existing := filepath.Join(destRoot, filepath.FromSlash(rel))

		current, err := os.ReadFile(existing)
		if err != nil {
			if !os.IsNotExist(err) {
				return nil, fmt.Errorf("read %s: %w", rel, err)
			}
			actions = append(actions, FileAction{Rel: rel, Action: ActionCreate})
			continue
		}
		next, err := os.ReadFile(staged)
		if err != nil {
			return nil, fmt.Errorf("read staged %s: %w", rel, err)
		}

		switch {
		case string(current) == string(next):
			actions = append(actions, FileAction{Rel: rel, Action: ActionIdentical})
		case force:
			actions = append(actions, FileAction{Rel: rel, Action: ActionOverwrite})
		default:
			actions = append(actions, FileAction{Rel: rel, Action: ActionSkipExists})
		}
	}
	return actions, nil
}

// assertForceIsSafe refuses a --force that would overwrite a pinned overlay.
//
// kustomize records a digest in the overlay's kustomization file, so replacing
// one with a freshly rendered skeleton un-deploys whatever that environment is
// running. There is no version of that a user meant to ask for, so this is a
// hard refusal rather than a warning, and it names every file so the fix is
// obvious.
func assertForceIsSafe(destRoot string, actions []FileAction) error {
	var pinned []string
	for _, a := range actions {
		if a.Action != ActionOverwrite || !isKustomizationFile(a.Rel) {
			continue
		}
		k, _, err := kustomize.ReadKustomization(filepath.Join(destRoot, filepath.FromSlash(path.Dir(a.Rel))))
		if err != nil {
			// Unreadable or absent: nothing to protect, and the render will
			// report a real problem if there is one.
			continue
		}
		for _, img := range k.Images {
			if img.Digest != "" {
				pinned = append(pinned, fmt.Sprintf("  %s pins %s at %s", a.Rel, img.Name, img.Digest))
				break
			}
		}
	}
	if len(pinned) == 0 {
		return nil
	}
	return fmt.Errorf("--force would overwrite %d overlay%s that pin a digest, un-deploying what they run:\n%s\n\nRemove those paths from the scaffold, or delete the overlay deliberately first.",
		len(pinned), plural(len(pinned)), strings.Join(pinned, "\n"))
}

func isKustomizationFile(rel string) bool {
	return slices.Contains(kustomize.KustomizationFileNames, path.Base(rel))
}

// applyStaged copies the staged files the actions say to write.
//
// Nothing is written until every action has been classified, so a failure part
// way through classification leaves the repository untouched.
func applyStaged(stagingDir, destRoot string, actions []FileAction) ([]string, error) {
	var written []string
	for _, a := range actions {
		if !a.Writes() {
			continue
		}
		src := filepath.Join(stagingDir, filepath.FromSlash(a.Rel))
		dst := filepath.Join(destRoot, filepath.FromSlash(a.Rel))
		if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
			return written, fmt.Errorf("create %s: %w", path.Dir(a.Rel), err)
		}
		data, err := os.ReadFile(src)
		if err != nil {
			return written, fmt.Errorf("read staged %s: %w", a.Rel, err)
		}
		if err := os.WriteFile(dst, data, 0o644); err != nil {
			return written, fmt.Errorf("write %s: %w", a.Rel, err)
		}
		written = append(written, a.Rel)
	}
	return written, nil
}

// OverlaysSegment is the skeleton directory whose contents may legitimately
// differ between environments.
const OverlaysSegment = "overlays/"

// mergeRendered folds one environment's render into the unit's staged tree.
//
// A skeleton is rendered once per environment, because the renderer has no way to
// emit one overlays/<env>/ directory per value — paths are templated, not
// iterated. Everything outside overlays/ must therefore come out identical on
// every pass, and this is where that is enforced: a file that differs between two
// environments means the author used an environment-varying value somewhere it
// does not belong, and silently keeping the last pass would be a tree whose base/
// only matches one environment.
func mergeRendered(from, into, env string) error {
	return filepath.WalkDir(from, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(from, p)
		if err != nil {
			return err
		}
		if rel == "." {
			return nil
		}
		target := filepath.Join(into, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}

		next, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		if current, err := os.ReadFile(target); err == nil {
			if string(current) == string(next) {
				return nil
			}
			if !strings.HasPrefix(filepath.ToSlash(rel), OverlaysSegment) {
				return fmt.Errorf("%s renders differently for environment %q than for an earlier one; a value that varies by environment may only be used under %s",
					filepath.ToSlash(rel), env, OverlaysSegment)
			}
		}
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return err
		}
		return os.WriteFile(target, next, 0o644)
	})
}

// componentRelPath is the repository-relative directory a component's manifests
// live in, slash-separated.
func componentRelPath(domain, system, component string) string {
	return gitops.Coordinate{Domain: domain, System: system, Component: component}.RelPath()
}

// summariseActions counts the actions by kind for the one-line report.
func summariseActions(actions []FileAction) string {
	counts := map[string]int{}
	for _, a := range actions {
		counts[a.Action]++
	}
	var parts []string
	for _, kind := range []string{ActionCreate, ActionOverwrite, ActionSkipExists, ActionIdentical} {
		if n := counts[kind]; n > 0 {
			parts = append(parts, fmt.Sprintf("%d %s", n, kind))
		}
	}
	if len(parts) == 0 {
		return "nothing to do"
	}
	return strings.Join(parts, ", ")
}

package deploy

import (
	"context"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
	"github.com/integrio-intropy/intropy-cli/internal/source"
)

// Plan is the outcome of editing an overlay and comparing the render before and
// after. It is produced without writing to git, so it is safe to build and
// discard.
type Plan struct {
	Coordinate  gitops.Coordinate
	Environment string
	Source      source.State

	// ReleaseVersion is the version the pins came from, empty when the digests
	// were resolved from the source repository's HEAD.
	//
	// A version rather than the manifest: nothing here needs more than the
	// version, and a promotion learns it from the source overlay's annotation
	// rather than from a manifest it never reads.
	ReleaseVersion string

	// PromotedFrom is the environment the digests were copied from, empty for a
	// deployment. A promotion resolves nothing — it copies — so this records
	// where the bits came from in place of a registry lookup.
	PromotedFrom string

	// Pins are the digests resolved for this commit.
	Pins []source.Pin

	// Previous records how each image was pinned before the edit, keyed by
	// image name, for a readable summary.
	Previous map[string]string

	// PreviousRelease is the version the target overlay was pinned from before
	// the edit, empty when it carried no release annotation.
	PreviousRelease string

	// Upstreams is what each environment this one promotes from currently has
	// pinned. Nil when the environment promotes from nothing. Informational: a
	// mismatch is reported, never enforced.
	Upstreams []Upstream

	// Notes are extra lines to print under the summary, already phrased. A
	// promotion uses them to say where the digests came from, which it knows
	// exactly and so has no upstream comparison to make.
	Notes []string

	// Diff is the unified diff of the rendered output. Empty means the edit
	// changed nothing.
	Diff string

	// DigestChanged reports whether any image's digest actually moved.
	DigestChanged bool

	// OverlayDir is the absolute path of the edited overlay.
	OverlayDir string

	// KustomizationPath is the file that was modified.
	KustomizationPath string
}

// Empty reports whether the plan would change nothing.
func (p *Plan) Empty() bool { return p.Diff == "" }

// ProvenanceOnly reports that the render changed but no image digest did — so
// the only difference is the source-commit annotation.
//
// Worth calling out rather than hiding: because kustomize propagates
// commonAnnotations into pod templates, this still rolls the pods. Suppressing
// the annotation instead would leave it disagreeing with the commit actually
// deployed, which is worse than a restart.
func (p *Plan) ProvenanceOnly() bool { return !p.Empty() && !p.DigestChanged }

// Summary renders the one-line-per-image human summary, followed by one line
// per environment this one promotes from.
func (p *Plan) Summary() string {
	var b strings.Builder
	if p.ReleaseVersion != "" {
		fmt.Fprintf(&b, "%s → %s (release %s, commit %s)\n", p.Coordinate, p.Environment, p.ReleaseVersion, p.Source.ShortCommit())
	} else {
		fmt.Fprintf(&b, "%s → %s (commit %s)\n", p.Coordinate, p.Environment, p.Source.ShortCommit())
	}
	for _, pin := range p.Pins {
		was := p.Previous[pin.Image]
		if was == "" {
			was = "(absent)"
		}
		fmt.Fprintf(&b, "  %s\n    %s → %s\n", pin.Image, was, pin.Digest)
	}
	b.WriteString(p.noteLines())
	return b.String()
}

// noteLines renders the plan's own notes and the promotesFrom comparison,
// indented to sit under the summary. Empty when there is neither — silence is
// the right output for an environment with no upstream.
func (p *Plan) noteLines() string {
	var b strings.Builder
	for _, note := range p.Notes {
		fmt.Fprintf(&b, "  %s\n", note)
	}
	for _, u := range p.Upstreams {
		fmt.Fprintf(&b, "  %s\n", u.Describe(p.Pins))
	}
	return b.String()
}

// pinnedAs names what the environment is already at, for the no-op message: a
// release version when there is one, otherwise the digest.
//
// Pins is never empty — component.yaml requires at least one image and both
// resolvers emit one pin per declared image — which is what makes the index
// safe here and in commitSubject.
func (p *Plan) pinnedAs() string {
	if p.ReleaseVersion != "" {
		return "release " + p.ReleaseVersion
	}
	return p.Pins[0].Digest
}

// PlanOptions configures BuildPlan.
type PlanOptions struct {
	Repository  *gitops.Repository
	Kustomize   kustomize.Client
	Coordinate  gitops.Coordinate
	Environment string
	Source      source.State

	// ReleaseVersion is annotated onto the overlay. Empty means the digests
	// came from a commit, and any release annotation already there is removed.
	ReleaseVersion string

	// PromotedFrom is the environment the digests were copied from, empty for a
	// deployment.
	PromotedFrom string

	Pins      []source.Pin
	Upstreams []Upstream

	// Notes are extra summary lines, already phrased.
	Notes []string

	OverlayDir string
	Palette    kustomize.Palette
}

// BuildPlan edits the overlay, renders before and after, and diffs them.
//
// On any failure — and when the diff turns out empty — the overlay is reverted,
// so the caller never has to reason about a half-edited worktree. The revert is
// scoped to the overlay directory: the cached checkout is shared, and an
// unscoped revert would discard anything else in it.
func BuildPlan(ctx context.Context, opts PlanOptions) (*Plan, error) {
	overlayRel := opts.Coordinate.OverlayRelPath(opts.Environment)

	current, kustPath, err := kustomize.ReadKustomization(opts.OverlayDir)
	if err != nil {
		return nil, err
	}

	previous := make(map[string]string, len(opts.Pins))
	digestChanged := false
	for _, pin := range opts.Pins {
		img, found := current.FindImage(pin.Image)
		if !found {
			previous[pin.Image] = ""
			digestChanged = true
			continue
		}
		previous[pin.Image] = img.Pinned()
		if img.Digest != pin.Digest {
			digestChanged = true
		}
	}

	before, err := opts.Kustomize.Build(ctx, opts.OverlayDir)
	if err != nil {
		return nil, err
	}
	beforeNorm, err := kustomize.Normalize(before)
	if err != nil {
		return nil, err
	}

	plan := &Plan{
		Coordinate:        opts.Coordinate,
		Environment:       opts.Environment,
		Source:            opts.Source,
		ReleaseVersion:    opts.ReleaseVersion,
		PromotedFrom:      opts.PromotedFrom,
		Pins:              opts.Pins,
		Previous:          previous,
		PreviousRelease:   current.CommonAnnotations[kustomize.AnnotationRelease],
		Upstreams:         opts.Upstreams,
		Notes:             opts.Notes,
		DigestChanged:     digestChanged,
		OverlayDir:        opts.OverlayDir,
		KustomizationPath: kustPath,
	}

	revert := func() error {
		return opts.Repository.Git.CheckoutPaths(ctx, overlayRel)
	}

	if err := applyEdits(ctx, opts, current); err != nil {
		return nil, withRevert(err, revert)
	}

	after, err := opts.Kustomize.Build(ctx, opts.OverlayDir)
	if err != nil {
		return nil, withRevert(err, revert)
	}
	afterNorm, err := kustomize.Normalize(after)
	if err != nil {
		return nil, withRevert(err, revert)
	}

	// An empty diff is not proof that the digest is already deployed. Existing
	// overlays often have no images[] entry, and `kustomize edit set image`
	// silently adds one — if the base never references that repository the pin
	// is inert, the render is unchanged, and reporting "already at that digest"
	// would be a lie. Confirm each pin actually reached the output.
	if err := assertPinsRendered(afterNorm, opts.Pins); err != nil {
		return nil, withRevert(err, revert)
	}

	plan.Diff = kustomize.Diff(beforeNorm, afterNorm, overlayRel+" (current)", overlayRel+" (planned)", opts.Palette)

	// Nothing to commit, so leave the checkout as we found it.
	if plan.Empty() {
		if err := revert(); err != nil {
			return nil, err
		}
	}
	return plan, nil
}

// applyEdits pins every digest and records where they came from.
//
// current is the overlay as it was before the edit, used only to decide whether
// there is a release annotation to remove.
func applyEdits(ctx context.Context, opts PlanOptions, current *kustomize.Kustomization) error {
	for _, pin := range opts.Pins {
		if err := opts.Kustomize.SetImage(ctx, opts.OverlayDir, pin.Image, pin.Digest); err != nil {
			return err
		}
	}
	if err := opts.Kustomize.SetAnnotation(ctx, opts.OverlayDir, kustomize.AnnotationSourceCommit, opts.Source.Commit); err != nil {
		return err
	}

	if opts.ReleaseVersion != "" {
		return opts.Kustomize.SetAnnotation(ctx, opts.OverlayDir, kustomize.AnnotationRelease, opts.ReleaseVersion)
	}
	// These digests came from a commit, so any version recorded here describes a
	// deployment that is being replaced. Leaving it would be worse than having
	// no annotation at all: a stale version beside an unrelated digest is read
	// as fact by promote, and would promote a version prod never ran.
	if _, found := current.CommonAnnotations[kustomize.AnnotationRelease]; found {
		return opts.Kustomize.RemoveAnnotation(ctx, opts.OverlayDir, kustomize.AnnotationRelease)
	}
	return nil
}

// assertPinsRendered checks that every pin reached the rendered output as the
// exact reference it should produce.
//
// Matching the full image@digest rather than the digest alone is essential. A
// bare digest search passes whenever the same digest is already pinned to some
// *other* image in the overlay — which happens routinely, since sibling images
// are often built from one source and share a digest — and that would let an
// inert pin report success, the precise failure this guard exists to catch.
//
// The declared name is the right thing to look for even when the overlay
// previously rewrote the repository with newName: `kustomize edit set image
// <name>@<digest>` replaces the whole images[] entry, dropping any newName, so
// the render always carries the declared repository afterwards.
func assertPinsRendered(rendered []byte, pins []source.Pin) error {
	text := string(rendered)
	for _, pin := range pins {
		if strings.Contains(text, pin.Ref()) {
			continue
		}
		return fmt.Errorf("pinning %s had no effect: %s does not appear in the rendered output.\nDoes the base reference %s? kustomize adds an images[] entry that matches nothing without applying it",
			pin.Image, pin.Ref(), pin.Image)
	}
	return nil
}

// Revert discards the overlay edits. Callers use it when they decide not to
// commit after building a plan.
func (p *Plan) Revert(ctx context.Context, repo *gitops.Repository) error {
	return repo.Git.CheckoutPaths(ctx, p.Coordinate.OverlayRelPath(p.Environment))
}

// RelKustomizationPath returns the modified file relative to the repository
// root, for staging.
func (p *Plan) RelKustomizationPath(root string) string {
	rel, err := filepath.Rel(root, p.KustomizationPath)
	if err != nil {
		return p.KustomizationPath
	}
	return filepath.ToSlash(rel)
}

// withRevert reverts the overlay and reports both failures if the revert also
// fails — leaving a dirty shared checkout silently would poison the next run.
func withRevert(cause error, revert func() error) error {
	if err := revert(); err != nil {
		return fmt.Errorf("%w (and the overlay could not be reverted: %v)", cause, err)
	}
	return cause
}

package deploy

import (
	"context"
	"fmt"
	"io"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
)

// session is the state every command in this package starts from: a refreshed
// GitOps checkout and the repository-level policy in it.
type session struct {
	repo      *gitops.Repository
	deployCfg *gitops.DeployConfig

	// argocdServer is argocdServer from the user's configuration file, the last
	// resort when neither the flag nor deploy.yaml names one.
	argocdServer string
}

// sessionOptions is the subset of a command's options openSession needs.
type sessionOptions struct {
	GitopsRepo   string
	ArgocdServer string
	CacheRoot    string
	Runner       command.Runner
	Stderr       io.Writer
}

// openSession resolves the GitOps repository, refreshes the cached checkout and
// loads deploy.yaml.
//
// binaries are required up front, before any network or cache work: discovering
// a missing kustomize after cloning wastes the user's time. Which ones is the
// caller's business — sync renders nothing, so demanding kustomize of it would
// be a prerequisite it never uses.
//
// The caller owns the returned repository and must Close it.
func openSession(ctx context.Context, opts sessionOptions, binaries ...string) (*session, error) {
	if err := command.RequireBinaries(binaries...); err != nil {
		return nil, err
	}

	cfg, err := config.Load()
	if err != nil {
		return nil, err
	}
	resolved := cfg.Resolve(config.Flags{GitopsRepo: opts.GitopsRepo, ArgocdServer: opts.ArgocdServer})
	repoURL, err := resolved.RequireGitopsRepo()
	if err != nil {
		return nil, err
	}

	fmt.Fprintf(opts.Stderr, "refreshing %s\n", repoURL)
	repo, err := gitops.Open(ctx, gitops.Options{URL: repoURL, Runner: opts.Runner, CacheRoot: opts.CacheRoot})
	if err != nil {
		return nil, err
	}

	deployCfg, err := gitops.LoadDeployConfig(repo.Root)
	if err != nil {
		repo.Close()
		return nil, err
	}

	return &session{repo: repo, deployCfg: deployCfg, argocdServer: resolved.ArgocdServer}, nil
}

func (s *session) Close() { s.repo.Close() }

// locateComponent finds the component in the GitOps tree and reads its
// component.yaml. domain and system disambiguate a name that occurs more than
// once.
func (s *session) locateComponent(component, domain, system string) (gitops.Coordinate, *gitops.ComponentConfig, error) {
	coord, err := gitops.FindComponent(s.repo.Root, component, domain, system)
	if err != nil {
		return gitops.Coordinate{}, nil, err
	}
	comp, err := gitops.LoadComponentConfig(componentDir(s.repo.Root, coord))
	if err != nil {
		return gitops.Coordinate{}, nil, err
	}
	return coord, comp, nil
}

// componentKind is the component's kind with the default made explicit, so a
// reported value never depends on whether component.yaml spelled it out.
func componentKind(comp *gitops.ComponentConfig) string {
	if comp.Kind == "" {
		return gitops.KindService
	}
	return comp.Kind
}

// requirePinnable rejects a component that has no image to pin.
//
// deploy and promote exist to move image digests, so a shared component is a
// category error for them rather than a run that happens to change nothing —
// without this the plan would come out empty and read as "already up to date".
// status, diff and sync all work on a shared component and must not call this.
func requirePinnable(coord gitops.Coordinate, comp *gitops.ComponentConfig) error {
	if !comp.IsShared() {
		return nil
	}
	return fmt.Errorf("%s is kind %q; it declares no images, so there is nothing to pin — edit its manifests directly", coord, gitops.KindShared)
}

package release

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/source"
)

// now is the clock, replaced in tests so a manifest is reproducible.
var now = time.Now

// Create publishes an immutable release manifest and pushes an annotated git
// tag. It changes no environment: what was running before is still running,
// and because the version resolves the same commit it resolves the same
// digests.
//
// Re-running for a version that already exists is safe. The existing manifest
// is compared against what this run would publish; if they agree, the release
// is left alone and only a missing git tag is repaired. If they disagree the
// version is being reused for something else, and that is refused.
func Create(ctx context.Context, opts Options) error {
	opts.applyDefaults()

	if opts.Version == "" {
		return errors.New("a version is required")
	}
	if err := command.RequireBinaries("git"); err != nil {
		return err
	}

	cfg, err := config.Load()
	if err != nil {
		return err
	}
	resolved := cfg.Resolve(config.Flags{GitopsRepo: opts.GitopsRepo})
	repoURL, err := resolved.RequireGitopsRepo()
	if err != nil {
		return err
	}

	fmt.Fprintf(opts.Stderr, "refreshing %s\n", repoURL)
	repo, err := gitops.Open(ctx, gitops.Options{URL: repoURL, Runner: opts.Runner, CacheRoot: opts.CacheRoot})
	if err != nil {
		return err
	}
	defer repo.Close()

	coord, err := gitops.FindComponent(repo.Root, opts.Component, opts.Domain, opts.System)
	if err != nil {
		return err
	}
	comp, err := gitops.LoadComponentConfig(gitops.JoinRel(repo.Root, coord.RelPath()))
	if err != nil {
		return err
	}
	if len(comp.Images) == 0 {
		return fmt.Errorf("%s declares no images, so there is nothing to release", coord)
	}

	g := git.Client{Runner: opts.Runner, Dir: opts.SourceDir}

	src, err := source.Inspect(ctx, g, comp.SourcePaths, opts.AllowDirty)
	if err != nil {
		return err
	}
	if len(src.Dirty) > 0 {
		fmt.Fprintf(opts.Stderr, "warning: releasing with %d uncommitted change(s) under the component's source paths\n", len(src.Dirty))
	}

	// Ref defaults to HEAD, which Inspect has already checked. A different ref
	// is resolved here and checked for reachability the same way.
	commit := src.Commit
	if opts.Ref != "HEAD" {
		commit, err = g.RevParse(ctx, opts.Ref)
		if err != nil {
			return fmt.Errorf("resolve --ref %s: %w", opts.Ref, err)
		}
		pushed, err := g.IsAncestor(ctx, commit, gitops.RemoteName+"/"+src.Branch)
		if err != nil {
			return err
		}
		if !pushed {
			return &source.UnpushedCommitError{Commit: commit, Branch: gitops.RemoteName + "/" + src.Branch}
		}
	}

	reg, err := NewRegistry(opts.UserAgent)
	if err != nil {
		return err
	}

	releasesRepo := ReleasesRepo(comp.Images[0].Name)
	ref := Ref(releasesRepo, opts.Version)

	// Look before publishing. A retry after a partial run has to recognise its
	// own earlier work, and that is only possible while the existing manifest
	// is still there to compare against.
	existing, err := lookup(ctx, reg, ref)
	if err != nil {
		return err
	}

	// Registry's Resolve matches source.Resolver, so no adapter is needed.
	pins, err := source.ResolveDigests(ctx, reg, comp, commit)
	if err != nil {
		return err
	}

	basis, from, err := resolveBasis(ctx, reg, g, releasesRepo, commit, opts.Since, opts.Version)
	if err != nil {
		return err
	}

	var changes []Change
	if from != "" {
		if changes, err = Changelog(ctx, g, from, commit, comp.SourcePaths); err != nil {
			return err
		}
	}

	m := &Manifest{
		SchemaVersion: SchemaVersion,
		Component:     coord.Component,
		Version:       opts.Version,
		CreatedAt:     now().UTC().Truncate(time.Second),
		CreatedBy:     committer(),
		Source:        Source{Commit: commit, Ref: opts.Ref, Repo: repoURL},
		Images:        images(pins),
		Changes:       changes,
		ChangeBasis:   basis,
	}
	m.Notes = RenderNotes(changes, basis)

	result := Result{
		Component: m.Component,
		Version:   m.Version,
		Ref:       ref,
		Tag:       TagName(coord.Component, opts.Version),
		Manifest:  m,
	}

	switch {
	case existing == nil:
		digest, err := Push(ctx, reg, ref, m)
		if err != nil {
			return err
		}
		result.Digest, result.Created = digest, true
		fmt.Fprintf(opts.Stderr, "published %s\n", ref)

	case existing.SameRelease(m):
		// Already published, identically. Report the release that exists
		// rather than the one this run would have built.
		desc, err := reg.Resolve(ctx, ref)
		if err != nil {
			return err
		}
		result.Digest, result.Manifest = desc.Digest, existing
		fmt.Fprintf(opts.Stderr, "%s already published; nothing to do\n", ref)

	default:
		return fmt.Errorf("%s already exists and describes a different release (%s vs %s)\n"+
			"a release is immutable: pick a new version, or delete the tag in the registry if it was published in error",
			ref, shortSHA(existing.Source.Commit), shortSHA(m.Source.Commit))
	}

	// Tag after publishing. The manifest is what a release is; the tag is a
	// convenience for people reading git log, and nothing in this CLI reads it
	// — release discovery goes through the registry. So a tag that cannot be
	// pushed is reported and does not fail the command, and re-running repairs
	// it against the manifest that already exists.
	result.Tagged = tag(ctx, g, result.Tag, commit, m, opts.Stderr)

	return report(opts, result)
}

// lookup reads the manifest already published at ref, if any.
func lookup(ctx context.Context, reg Registry, ref string) (*Manifest, error) {
	m, err := Pull(ctx, reg, ref)
	switch {
	case err == nil:
		return m, nil
	case errors.Is(err, ErrNotFound):
		return nil, nil
	case errors.Is(err, ErrNotRelease):
		// Something else holds this tag. Publishing over it would destroy
		// whatever it is.
		return nil, fmt.Errorf("%s already exists and is not a release manifest: %w", ref, err)
	default:
		return nil, err
	}
}

// resolveBasis decides what the changelog is measured against, and returns the
// commit to start from. An empty from means there is nothing to measure.
func resolveBasis(ctx context.Context, reg Registry, g git.Client, releasesRepo, commit, since, version string) (ChangeBasis, string, error) {
	if since != "" {
		from, err := g.RevParse(ctx, since)
		if err != nil {
			return ChangeBasis{}, "", fmt.Errorf("resolve --since %s: %w", since, err)
		}
		ancestor, err := g.IsAncestor(ctx, from, commit)
		if err != nil {
			return ChangeBasis{}, "", err
		}
		if !ancestor {
			return ChangeBasis{}, "", fmt.Errorf("--since %s is not an ancestor of the commit being released (%s), so there is no range between them", since, shortSHA(commit))
		}
		return ChangeBasis{Kind: BasisExplicit, Ref: since}, from, nil
	}

	prev, err := PreviousRelease(ctx, reg, g, releasesRepo, commit, version)
	if err != nil {
		return ChangeBasis{}, "", err
	}
	if prev == nil {
		// Nothing was released, so there is no prior state to diff against.
		// The window is undefined rather than large, and saying so beats
		// synthesising one: the first managed release of a component is
		// usually adoption, not birth, and --since is how an operator names
		// the point the tool cannot know.
		return ChangeBasis{Kind: BasisInitial}, "", nil
	}
	return ChangeBasis{
		Kind:    BasisRelease,
		Version: prev.Version,
		Commit:  prev.Source.Commit,
	}, prev.Source.Commit, nil
}

// TagName is the annotated tag for a release. Component-prefixed because these
// are monorepos: a bare v1.4.2 would collide the moment a second component in
// the same repository cut a release.
func TagName(component, version string) string {
	return component + "/v" + version
}

// tag creates and pushes the annotated tag, reporting whether it reached the
// remote. Every failure is a warning: the release is already published, and
// the tag is not load-bearing.
func tag(ctx context.Context, g git.Client, name, commit string, m *Manifest, stderr io.Writer) bool {
	at, exists, err := g.TagCommit(ctx, name)
	if err != nil {
		fmt.Fprintf(stderr, "warning: could not read tag %s: %v\n", name, err)
		return false
	}

	switch {
	case exists && at != commit:
		fmt.Fprintf(stderr, "warning: tag %s already points at %s, not %s; leaving it alone\n", name, shortSHA(at), shortSHA(commit))
		return false
	case !exists:
		if err := g.Tag(ctx, name, tagMessage(m), commit); err != nil {
			fmt.Fprintf(stderr, "warning: could not create tag %s: %v\n", name, err)
			return false
		}
	}

	// Pushing a tag the remote already has is a no-op, which is what makes
	// this safe to repeat.
	if err := g.Push(ctx, gitops.RemoteName, "refs/tags/"+name); err != nil {
		fmt.Fprintf(stderr, "warning: release %s is published, but its git tag could not be pushed: %v\n", m.Version, err)
		fmt.Fprintf(stderr, "         the release is valid without it; re-run to repair the tag\n")
		return false
	}
	fmt.Fprintf(stderr, "tagged %s\n", name)
	return true
}

func tagMessage(m *Manifest) string {
	return fmt.Sprintf("%s %s\n\n%s", m.Component, m.Version, m.Notes)
}

func images(pins []source.Pin) []Image {
	out := make([]Image, 0, len(pins))
	for _, p := range pins {
		out = append(out, Image{Name: p.Image, Digest: p.Digest})
	}
	return out
}

func committer() string {
	for _, key := range []string{"GITLAB_USER_EMAIL", "GITHUB_ACTOR", "USER"} {
		if v := os.Getenv(key); v != "" {
			return v
		}
	}
	return ""
}

func report(opts Options, r Result) error {
	if opts.OutputFormat == OutputJSON {
		enc := json.NewEncoder(opts.Stdout)
		enc.SetIndent("", "  ")
		return enc.Encode(r)
	}
	return renderCreated(opts.Stdout, r)
}

// Package source reads the state of a component's source repository: which
// commit is being shipped, whether it is safe to ship, and which image digests
// CI published for it.
//
// It is shared by the commands that need to name a specific build — deploy
// pins those digests into an overlay, release records them in a manifest — so
// it sits below both rather than inside either.
package source

import (
	"context"
	"fmt"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
)

// State is what the source repository says about the commit being shipped.
type State struct {
	// Commit is the full sha of HEAD.
	Commit string

	// Branch is the source remote's default branch, the one CI builds.
	Branch string

	// Dirty lists uncommitted changes under the component's source paths. It
	// is populated even when the check is waived, so callers can warn.
	Dirty []string
}

// ShortCommit abbreviates the commit for messages and commit subjects.
func (s State) ShortCommit() string { return git.ShortSHA(s.Commit) }

// Inspect reads the state of the source repository at dir and checks that its
// HEAD is a safe thing to ship.
//
// Two conditions are enforced. The working tree must be clean under the
// component's source paths, because CI built the pushed commit and uncommitted
// changes mean the thing about to be shipped is not the thing that was just
// tested. And HEAD must be an ancestor of the remote's default branch, because
// an unpushed commit has no image in the registry at all.
//
// The cleanliness check is scoped to sourcePaths rather than applied to the
// whole tree: these are monorepos holding many components, and an unrelated
// dirty file elsewhere is no reason to refuse. allowDirty waives the check but
// not the reporting.
func Inspect(ctx context.Context, g git.Client, sourcePaths []string, allowDirty bool) (State, error) {
	var st State

	commit, err := g.HEAD(ctx)
	if err != nil {
		return st, err
	}
	st.Commit = commit

	dirty, err := g.Status(ctx, sourcePaths...)
	if err != nil {
		return st, err
	}
	st.Dirty = dirty
	if len(dirty) > 0 && !allowDirty {
		return st, &DirtyWorktreeError{Paths: sourcePaths, Changes: dirty}
	}

	branch, err := g.DefaultBranch(ctx, gitops.RemoteName)
	if err != nil {
		return st, err
	}
	st.Branch = branch

	// Fetch before reasoning about ancestry. A stale remote-tracking ref makes
	// a commit that was pushed yesterday look unpushed, which is the most
	// confusing possible version of this error.
	if err := g.Fetch(ctx, gitops.RemoteName, branch); err != nil {
		return st, err
	}
	remoteRef := gitops.RemoteName + "/" + branch
	pushed, err := g.IsAncestor(ctx, commit, remoteRef)
	if err != nil {
		return st, err
	}
	if !pushed {
		return st, &UnpushedCommitError{Commit: commit, Branch: remoteRef}
	}

	return st, nil
}

// DirtyWorktreeError reports uncommitted changes in the component's source.
type DirtyWorktreeError struct {
	Paths   []string
	Changes []string
}

func (e *DirtyWorktreeError) Error() string {
	var b strings.Builder
	scope := "the working tree"
	if len(e.Paths) > 0 {
		scope = strings.Join(e.Paths, ", ")
	}
	fmt.Fprintf(&b, "uncommitted changes under %s:", scope)
	for _, c := range e.Changes {
