207	// Commit records the staged changes. Each message becomes a paragraph, which is
208	// how a subject line and a trailer block are produced without a temporary file:
209	// git separates -m arguments with a blank line, and trailers only need to be
210	// the final paragraph to be parseable by `git log --format=%(trailers)`.
211	//
212	// Nothing is staged implicitly — there is no -a — so the caller decides exactly
213	// what the commit contains.
214	func (g Client) Commit(ctx context.Context, messages ...string) error {
215		if len(messages) == 0 {
216			return errors.New("Commit requires at least a subject")
217		}
218		args := []string{"commit", "--quiet"}
219		for _, m := range messages {
220			args = append(args, "-m", m)
221		}
222		if _, err := g.run(ctx, args...); err != nil {
223			return fmt.Errorf("commit: %w", err)
224		}
225		return nil
226	}
