336	// Push pushes refspec to remote.
337	//
338	// A rejection is reported as *PushRejectedError so callers can rebase and retry,
339	// distinguished from an authentication or network failure where retrying is
340	// pointless.
341	func (g Client) Push(ctx context.Context, remote, refspec string) error {
342		_, err := g.run(ctx, "push", "--quiet", remote, refspec)
343		if err == nil {
344			return nil
345		}
346		if ee, ok := errors.AsType[*command.ExitError](err); ok && isRejection(ee.Stderr) {
347			return &PushRejectedError{Remote: remote, Refspec: refspec, Stderr: ee.Stderr}
348		}
349		return fmt.Errorf("push %s %s: %w", remote, refspec, err)
350	}
