376	// Rebase replays the current branch onto upstream.
377	//
378	// A conflict is reported as *RebaseConflictError with the rebase left in
379	// progress, so the caller can decide — this package must not abort on the
380	// caller's behalf, because whether a conflict is recoverable is policy.
381	func (g Client) Rebase(ctx context.Context, upstream string) error {
382		_, err := g.run(ctx, "rebase", upstream)
383		if err == nil {
384			return nil
385		}
386		if ee, ok := errors.AsType[*command.ExitError](err); ok {
387			return &RebaseConflictError{Upstream: upstream, Stderr: ee.Stderr}
388		}
389		return fmt.Errorf("rebase onto %s: %w", upstream, err)
390	}

160	// unscoped revert would discard anything else in it.
161	func BuildPlan(ctx context.Context, opts PlanOptions) (*Plan, error) {
162		overlayRel := opts.Coordinate.OverlayRelPath(opts.Environment)
163	
164		current, kustPath, err := kustomize.ReadKustomization(opts.OverlayDir)
165		if err != nil {
166			return nil, err
167		}
168	
169		previous := make(map[string]string, len(opts.Pins))
170		digestChanged := false
171		for _, pin := range opts.Pins {
172			img, found := current.FindImage(pin.Image)
173			if !found {
174				previous[pin.Image] = ""
175				digestChanged = true
176				continue
177			}
178			previous[pin.Image] = img.Pinned()
179			if img.Digest != pin.Digest {
180				digestChanged = true
181			}
182		}
183	
184		before, err := opts.Kustomize.Build(ctx, opts.OverlayDir)
185		if err != nil {
186			return nil, err
187		}
188		beforeNorm, err := kustomize.Normalize(before)
189		if err != nil {
190			return nil, err
191		}
192	
193		plan := &Plan{
194			Coordinate:        opts.Coordinate,
195			Environment:       opts.Environment,
196			Source:            opts.Source,
197			ReleaseVersion:    opts.ReleaseVersion,
198			PromotedFrom:      opts.PromotedFrom,
199			Pins:              opts.Pins,
200			Previous:          previous,
201			PreviousRelease:   current.CommonAnnotations[kustomize.AnnotationRelease],
202			Upstreams:         opts.Upstreams,
203			Notes:             opts.Notes,
204			DigestChanged:     digestChanged,
205			OverlayDir:        opts.OverlayDir,
206			KustomizationPath: kustPath,
207		}
208	
209		revert := func() error {
210			return opts.Repository.Git.CheckoutPaths(ctx, overlayRel)
211		}
212	
213		if err := applyEdits(ctx, opts, current); err != nil {
214			return nil, withRevert(err, revert)
215		}
216	
217		after, err := opts.Kustomize.Build(ctx, opts.OverlayDir)
218		if err != nil {
219			return nil, withRevert(err, revert)
220		}
221		afterNorm, err := kustomize.Normalize(after)
222		if err != nil {
223			return nil, withRevert(err, revert)
224		}
225	
226		// An empty diff is not proof that the digest is already deployed. Existing
227		// overlays often have no images[] entry, and `kustomize edit set image`
228		// silently adds one — if the base never references that repository the pin
229		// is inert, the render is unchanged, and reporting "already at that digest"
230		// would be a lie. Confirm each pin actually reached the output.
231		if err := assertPinsRendered(afterNorm, opts.Pins); err != nil {
232			return nil, withRevert(err, revert)
233		}
234	
235		plan.Diff = kustomize.Diff(beforeNorm, afterNorm, overlayRel+" (current)", overlayRel+" (planned)", opts.Palette)
236	
237		// Nothing to commit, so leave the checkout as we found it.
238		if plan.Empty() {
239			if err := revert(); err != nil {
240				return nil, err
241			}
242		}
243		return plan, nil
244	}
245	
246	// applyEdits pins every digest and records where they came from.
247	//
248	// current is the overlay as it was before the edit, used only to decide whether
249	// there is a release annotation to remove.
250	func applyEdits(ctx context.Context, opts PlanOptions, current *kustomize.Kustomization) error {
251		for _, pin := range opts.Pins {
252			if err := opts.Kustomize.SetImage(ctx, opts.OverlayDir, pin.Image, pin.Digest); err != nil {
253				return err
254			}
255		}
256		if err := opts.Kustomize.SetAnnotation(ctx, opts.OverlayDir, kustomize.AnnotationSourceCommit, opts.Source.Commit); err != nil {
257			return err
258		}
259	
260		if opts.ReleaseVersion != "" {
261			return opts.Kustomize.SetAnnotation(ctx, opts.OverlayDir, kustomize.AnnotationRelease, opts.ReleaseVersion)
262		}
263		// These digests came from a commit, so any version recorded here describes a
264		// deployment that is being replaced. Leaving it would be worse than having
265		// no annotation at all: a stale version beside an unrelated digest is read
266		// as fact by promote, and would promote a version prod never ran.
267		if _, found := current.CommonAnnotations[kustomize.AnnotationRelease]; found {
268			return opts.Kustomize.RemoveAnnotation(ctx, opts.OverlayDir, kustomize.AnnotationRelease)
269		}
270		return nil
271	}
272	
273	// assertPinsRendered checks that every pin reached the rendered output as the
274	// exact reference it should produce.
275	//
276	// Matching the full image@digest rather than the digest alone is essential. A
277	// bare digest search passes whenever the same digest is already pinned to some
278	// *other* image in the overlay — which happens routinely, since sibling images
279	// are often built from one source and share a digest — and that would let an
280	// inert pin report success, the precise failure this guard exists to catch.
281	//
282	// The declared name is the right thing to look for even when the overlay
283	// previously rewrote the repository with newName: `kustomize edit set image
284	// <name>@<digest>` replaces the whole images[] entry, dropping any newName, so
285	// the render always carries the declared repository afterwards.
286	func assertPinsRendered(rendered []byte, pins []source.Pin) error {
287		text := string(rendered)
288		for _, pin := range pins {
289			if strings.Contains(text, pin.Ref()) {
290				continue
291			}
292			return fmt.Errorf("pinning %s had no effect: %s does not appear in the rendered output.\nDoes the base reference %s? kustomize adds an images[] entry that matches nothing without applying it",
293				pin.Image, pin.Ref(), pin.Image)
294		}
295		return nil
296	}
