298	// Revert discards the overlay edits. Callers use it when they decide not to
299	// commit after building a plan.
300	func (p *Plan) Revert(ctx context.Context, repo *gitops.Repository) error {
301		return repo.Git.CheckoutPaths(ctx, p.Coordinate.OverlayRelPath(p.Environment))
302	}
