 70	func (o *PublishOptions) applyDefaults() {
 71		if o.MaxAttempts <= 0 {
 72			o.MaxAttempts = maxPushAttempts
 73		}
 74		if o.Backoff == nil {
 75			o.Backoff = jitteredBackoff
 76		}
 77		if o.Sleep == nil {
 78			o.Sleep = time.Sleep
 79		}
 80		if o.Stderr == nil {
 81			o.Stderr = io.Discard
 82		}
 83	}
