 85	// Publish commits the overlay change and pushes it, rebasing and retrying if
 86	// someone else pushed first.
 87	//
 88	// It returns the sha that actually landed on the remote. That is not necessarily
 89	// the sha of the first commit: a rebase rewrites it, and every later step — the
 90	// ArgoCD revision gate above all — must reason about the final one.
 91	func Publish(ctx context.Context, opts PublishOptions) (string, error) {
 92		opts.applyDefaults()
 93	
 94		repo := opts.Repository
 95		plan := opts.Plan
 96		rel := plan.RelKustomizationPath(repo.Root)
 97	
 98		// Stage only the file the plan changed. A blanket `git add -A` in a shared
 99		// checkout would sweep up anything else that happened to be there.
100		if err := repo.Git.Add(ctx, rel); err != nil {
101			return "", err
102		}
103		if err := repo.Git.Commit(ctx, commitSubject(plan), commitTrailers(plan, opts.CliVersion)); err != nil {
104			return "", err
105		}
106	
107		refspec := "HEAD:" + repo.Branch
108		remoteRef := gitops.RemoteName + "/" + repo.Branch
109	
110		for attempt := 1; ; attempt++ {
111			err := repo.Git.Push(ctx, gitops.RemoteName, refspec)
112			if err == nil {
113				return repo.Git.HEAD(ctx)
114			}
115	
116			var rejected *git.PushRejectedError
117			if !errors.As(err, &rejected) {
118				// Authentication, network, a missing remote: retrying cannot help.
119				return "", err
120			}
121			if attempt >= opts.MaxAttempts {
122				return "", fmt.Errorf("gave up after %d push attempt%s: %s is being deployed to concurrently — try again",
123					opts.MaxAttempts, plural(opts.MaxAttempts), repo.Branch)
124			}
125	
126			fmt.Fprintf(opts.Stderr, "push rejected; rebasing onto %s and retrying (%d/%d)\n", remoteRef, attempt+1, opts.MaxAttempts)
127			opts.Sleep(opts.Backoff(attempt))
128	
129			if err := repo.Git.Fetch(ctx, gitops.RemoteName, repo.Branch); err != nil {
130				return "", err
131			}
132			if err := repo.Git.Rebase(ctx, remoteRef); err != nil {
133				var conflict *git.RebaseConflictError
134				if !errors.As(err, &conflict) {
135					return "", err
136				}
137				// A conflict here means someone deployed the *same component to the
138				// same environment* in the same moment, so both commits edit the
139				// same line. Auto-resolving would silently pick a winner and
140				// discard a deployment someone believes succeeded.
141				if abortErr := repo.Git.RebaseAbort(ctx); abortErr != nil {
142					return "", fmt.Errorf("%w (and the rebase could not be aborted: %v)", err, abortErr)
143				}
144				return "", fmt.Errorf("another deployment of %s to %s landed at the same moment, and the two changes conflict.\nNothing was pushed. Re-run to deploy on top of theirs",
145					plan.Coordinate, plan.Environment)
146			}
147		}
148	}
