150	// commitSubject is the one-line summary. The digest is abbreviated: a full one
151	// makes the subject unreadable in a log, and the trailer carries it in full.
152	//
153	// A release deploy names the version instead of the digest. A release is
154	// immutable, so the version identifies those digests exactly and is the more
155	// useful thing to read in a log; the trailers still carry every digest in full.
672	// publishScaffold writes the staged files on a fresh branch and pushes it.
673	//
674	// Never to the default branch: the tree is full of placeholders and unpinned
675	// images, and the ApplicationSet would generate Applications for it the moment it
676	// landed. A branch is the reviewable artefact.
677	//
678	// Publish is not reused: it is wired to a Plan and its rebase-retry loop is for a
679	// one-line contended edit. A fresh branch that is rejected already exists on the
680	// remote, which is a clear error rather than something to retry.
681	func publishScaffold(ctx context.Context, opts InitOptions, repo *gitops.Repository, p publishScaffoldOptions) (publishedScaffold, error) {
682		start := gitops.RemoteName + "/" + repo.Branch
683		if err := repo.Git.CreateBranch(ctx, p.Branch, start); err != nil {
684			return publishedScaffold{}, err
685		}
686		// Unconditionally, on success and on failure alike: the refresh on the next
687		// Open resets whatever branch is current to the default branch's remote head,
688		// so leaving the checkout here would silently discard these commits.
689		defer func() {
690			if err := repo.Git.Switch(ctx, repo.Branch); err != nil {
691				fmt.Fprintf(opts.Stderr, "warning: could not restore %s in the cached checkout: %v\n", repo.Branch, err)
692			}
693		}()
694	
695		written, err := applyStaged(p.StagingDir, repo.Root, p.Actions)
696		if err != nil {
697			return publishedScaffold{}, err
698		}
699		// Only the paths staged, never `add -A`: the checkout is shared, and a
700		// concurrent run's debris is not ours to commit.
701		if err := repo.Git.Add(ctx, written...); err != nil {
702			return publishedScaffold{}, err
703		}
704		if err := repo.Git.Commit(ctx, scaffoldSubject(p.Facts, len(written)), scaffoldTrailers(p.Facts, opts.CliVersion)); err != nil {
705			return publishedScaffold{}, err
706		}
707		if err := repo.Git.Push(ctx, gitops.RemoteName, "HEAD:refs/heads/"+p.Branch); err != nil {
708			return publishedScaffold{}, fmt.Errorf("push %s: %w\n\nA rejection here usually means the branch already exists on the remote. Delete it, or merge the open review first.", p.Branch, err)
709		}
710	
711		revision, err := repo.Git.HEAD(ctx)
712		if err != nil {
713			return publishedScaffold{}, err
714		}
715		// While the branch is still current — the deferred switch above takes these
716		// files back out of the working tree.
717		placeholders, err := scanPlaceholders(repo.Root, p.Rels)
718		if err != nil {
719			return publishedScaffold{}, err
720		}
721		return publishedScaffold{Revision: revision, Placeholders: placeholders}, nil
722	}
